import os
from datetime import datetime


def read_playlist(folder):
    tracks = []
    with open(os.path.join(folder, "playlist.m3u"), "r", encoding="utf-8") as f:
        for line in f:
            name = line.strip()
            if name and not name.startswith("#"):
                tracks.append(name)
    return tracks


def read_metadata(folder):
    meta = {}
    with open(os.path.join(folder, "album_metadata.csv"), "r", encoding="utf-8") as f:
        for line in f:
            parts = [p.strip() for p in line.strip().split(",")]
            if len(parts) >= 3:
                meta[parts[0]] = {"artist": parts[1], "album": parts[2]}
    return meta


def read_ratings(folder):
    ratings = {}
    with open(os.path.join(folder, "ratings.txt"), "r", encoding="utf-8") as f:
        for line in f:
            if "=" not in line:
                continue
            track, score = line.split("=", 1)
            try:
                ratings[track.strip()] = float(score.strip())
            except ValueError:
                continue
    return ratings


def write_favourites(folder, favourites):
    with open(os.path.join(folder, "favourites.txt"), "w", encoding="utf-8") as f:
        for track, score in favourites:
            f.write("%.1f\t%s\n" % (score, track))


def write_missing(folder, missing):
    with open(os.path.join(folder, "missing_metadata.txt"), "w", encoding="utf-8") as f:
        for track in missing:
            f.write(track + "\n")


def write_restructure_script(folder, meta, tracks):
    path = os.path.join(folder, "restructure.sh")
    with open(path, "w", encoding="utf-8") as f:
        f.write("#!/bin/sh\n")
        for track in tracks:
            info = meta.get(track)
            if info:
                target = os.path.join(info["artist"], info["album"])
                f.write('mkdir -p "%s"\n' % target)
                f.write('mv "%s" "%s/"\n' % (track, target))
    os.chmod(path, 0o755)


def write_artist_summary(folder, meta, tracks):
    counts = {}
    for track in tracks:
        info = meta.get(track)
        if info:
            counts[info["artist"]] = counts.get(info["artist"], 0) + 1
    with open(os.path.join(folder, "artist_summary.txt"), "w", encoding="utf-8") as f:
        for artist in sorted(counts, key=lambda a: (-counts[a], a)):
            f.write("%-30s %d track(s)\n" % (artist, counts[artist]))


def organize(folder, threshold=4.0):
    tracks = read_playlist(folder)
    meta = read_metadata(folder)
    ratings = read_ratings(folder)

    favourites = sorted(
        ((t, ratings[t]) for t in tracks if ratings.get(t, 0.0) >= threshold),
        key=lambda item: (-item[1], item[0]),
    )
    missing = [t for t in tracks if t not in meta]

    write_favourites(folder, favourites)
    write_missing(folder, missing)
    write_restructure_script(folder, meta, tracks)
    write_artist_summary(folder, meta, tracks)

    with open(os.path.join(folder, "history.log"), "a", encoding="utf-8") as f:
        f.write("%s processed=%d favourites=%d missing=%d\n" % (
            datetime.now().isoformat(timespec="seconds"),
            len(tracks), len(favourites), len(missing)))
    return {"processed": len(tracks), "favourites": len(favourites), "missing": len(missing)}


if __name__ == "__main__":
    import sys
    target = sys.argv[1] if len(sys.argv) > 1 else "."
    stats = organize(target)
    print("processed %(processed)d tracks, %(favourites)d favourites, %(missing)d without metadata" % stats)

