def read_ballots(path):
    tallies = {}
    spoiled = {}
    with open(path, "r") as f:
        for line in f:
            row = line.strip()
            if not row:
                continue
            kind, label, count = row.split(",")
            if kind == "valid":
                tallies[label] = tallies.get(label, 0) + int(count)
            else:
                spoiled[label] = spoiled.get(label, 0) + int(count)
    return tallies, spoiled


def read_voters(path):
    groups = {}
    with open(path, "r") as f:
        for line in f:
            row = line.strip()
            if not row:
                continue
            group, registered, voted = row.split(",")
            entry = groups.setdefault(group, [0, 0])
            entry[0] += int(registered)
            entry[1] += int(voted)
    return groups


def read_margins(path):
    margins = []
    with open(path, "r") as f:
        for line in f:
            row = line.strip()
            if row:
                margins.append(float(row.split(",")[1]))
    return margins


def compute_percentages(tallies):
    total = sum(tallies.values())
    if total == 0:
        return {}, 0
    return {name: votes * 100.0 / total for name, votes in tallies.items()}, total


def write_winners(path, precinct, ranking):
    with open(path, "w") as f:
        f.write("Declared winners report for precinct %s\n" % precinct)
        for place, (name, share) in enumerate(ranking, start=1):
            f.write("%d. %s %.2f%%\n" % (place, name, share))


def write_recount(path, precinct, margin, anomaly):
    with open(path, "w") as f:
        if margin < 1.0:
            f.write("%s,close_race,%.2f\n" % (precinct, margin))
        if anomaly:
            f.write("%s,historic_anomaly,%.2f\n" % (precinct, margin))


def write_spoiled(path, spoiled):
    with open(path, "w") as f:
        for reason in sorted(spoiled):
            f.write("%s: %d ballots\n" % (reason, spoiled[reason]))
        f.write("total spoiled: %d\n" % sum(spoiled.values()))


def write_turnout(path, groups):
    with open(path, "w") as f:
        for group in sorted(groups):
            registered, voted = groups[group]
            rate = voted * 100.0 / registered if registered else 0.0
            f.write("%s,%d,%d,%.2f\n" % (group, registered, voted, rate))


def append_certification(path, precinct, winner, share, valid, spoiled_total):
    with open(path, "a") as f:
        f.write("%s,%s,%.2f,%d,%d\n" % (precinct, winner, share, valid, spoiled_total))


def analyze(precinct):
    tallies, spoiled = read_ballots("ballots_%s.csv" % precinct)
    groups = read_voters("voters_%s.csv" % precinct)
    margins = read_margins("margins_%s.csv" % precinct)
    shares, valid_total = compute_percentages(tallies)
    ranking = sorted(shares.items(), key=lambda item: -item[1])
    winner, winner_share = ranking[0] if ranking else ("none", 0.0)
    runner_up = ranking[1][1] if len(ranking) > 1 else 0.0
    margin = winner_share - runner_up
    average = sum(margins) / len(margins) if margins else margin
    anomaly = abs(margin - average) > 20.0
    write_winners("winners_%s.txt" % precinct, precinct, ranking)
    write_recount("recounts_%s.csv" % precinct, precinct, margin, anomaly)
    write_spoiled("spoiled_%s.txt" % precinct, spoiled)
    write_turnout("turnout_%s.csv" % precinct, groups)
    spoiled_total = sum(spoiled.values())
    append_certification("state_certification.log", precinct, winner,
                         winner_share, valid_total, spoiled_total)
    return {"precinct": precinct, "winner": winner, "share": winner_share,
            "margin": margin, "anomaly": anomaly, "valid": valid_total,
            "spoiled": spoiled_total}


def main():
