        title, reels = line.split(":", 1)
        attachments[title.strip()] = [r.strip() for r in reels.split(",") if r.strip()]
    f.close()
    return attachments


def read_ratings(path):
    ratings = {}
    f = open(path, "r", encoding="utf-8")
    for line in f:
        parts = [p.strip() for p in line.split(",")]
        if len(parts) == 3:
            ratings[parts[0]] = (parts[1], int(parts[2]))
    f.close()
    return ratings


def write_playlist(path, shows, attachments):
    f = open(path, "w", encoding="utf-8")
    for show in shows:
        f.write("SCREEN %s @ %s\n" % (show["screen"], show["start"].strftime("%H:%M")))
        for reel in attachments.get(show["title"], []):
            f.write("  PLAY TRAILER %s\n" % reel)
        f.write("  PLAY FEATURE %s (%d min)\n" % (show["title"], show["runtime"]))
    f.close()


def write_lobby_board(path, shows, ratings):
    f = open(path, "w", encoding="utf-8")
    f.write("TODAY AT THE MOVIES\n")
    for show in shows:
        rating, min_age = ratings.get(show["title"], ("NR", 18))
        f.write("%-6s %-30s Screen %-3s %s (age %d+)\n" % (
            show["start"].strftime("%H:%M"), show["title"], show["screen"], rating, min_age))
    f.close()


def write_pricing_sheet(path, shows, ratings):
    f = open(path, "w", encoding="utf-8")
    for show in shows:
        rating, min_age = ratings.get(show["title"], ("NR", 18))
        price = 9.50 if show["start"].hour < 17 else 13.00
        if min_age >= 18:
            price += 1.50
        f.write("%s;%s;%s;%.2f\n" % (show["screen"], show["start"].strftime("%H:%M"), show["title"], price))
    f.close()


def write_cleaning_schedule(path, shows):
    f = open(path, "w", encoding="utf-8")
    for show in shows:
        end = show["start"] + timedelta(minutes=show["runtime"])
        f.write("Screen %s: clean %s - %s after %s\n" % (
            show["screen"], end.strftime("%H:%M"),
            (end + timedelta(minutes=15)).strftime("%H:%M"), show["title"]))
    f.close()


def append_ticket_volume(path, multiplex, tickets):
    f = open(path, "a", encoding="utf-8")
    f.write("%s\t%s\t%d tickets\n" % (datetime.now().strftime("%Y-%m-%d"), multiplex, tickets))
    f.close()


def project(multiplex):
    at = lambda name: os.path.join(multiplex, name)
    shows = read_showtimes(at("showtimes.txt"))
    attachments = read_trailers(at("trailers.txt"))
    ratings = read_ratings(at("age_ratings.csv"))
    write_playlist(at("projector_playlist.cue"), shows, attachments)
    write_lobby_board(at("lobby_board.txt"), shows, ratings)
    write_pricing_sheet(at("box_office_prices.csv"), shows, ratings)
    write_cleaning_schedule(at("cleaning_schedule.txt"), shows)
    tickets = sum(show["sold"] for show in shows)
    append_ticket_volume(at("corporate.log"), multiplex, tickets)
    return tickets


def main():
    if len(sys.argv) != 2:
        print("usage: %s <multiplex-directory>" % sys.argv[0])
        return 1
    print("scheduled %d tickets" % project(sys.argv[1]))
    return 0


if __name__ == "__main__":
    sys.exit(main())

