import os
from datetime import date


def load_titles(path):
    titles = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            title = line.strip()
            if title:
                titles.append(title)
    return titles


def load_conditions(path):
    conditions = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if "|" in line:
                title, state = line.split("|", 1)
                conditions[title.strip()] = state.strip().lower()
    return conditions


def load_catalog_ids(path):
    catalog = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if "|" in line:
                title, number = line.split("|", 1)
                catalog[title.strip()] = number.strip()
    return catalog


def categorize(titles, conditions, catalog):
    shelf, repair, rare, unverified = [], [], [], []
    for title in titles:
        state = conditions.get(title, "unknown")
        number = catalog.get(title)
        if number is None:
            unverified.append(title)
        elif state == "damaged":
            repair.append((title, number))
        elif state == "fragile" or number.startswith("R"):
            rare.append((title, number))
        else:
            shelf.append((title, number))
    return shelf, repair, rare, unverified


def ingest(batch):
    titles = load_titles(os.path.join(batch, "titles.txt"))
    conditions = load_conditions(os.path.join(batch, "conditions.txt"))
    catalog = load_catalog_ids(os.path.join(batch, "catalog_ids.txt"))
    shelf, repair, rare, unverified = categorize(titles, conditions, catalog)

    with open(os.path.join(batch, "shelf_guide.txt"), "w", encoding="utf-8") as f:
        for title, number in shelf:
            f.write("{}\t{}\tsection {}\n".format(number, title, number[0]))

    with open(os.path.join(batch, "repair_slip.txt"), "w", encoding="utf-8") as f:
        f.write("REPAIR SHOP ROUTING SLIP {}\n".format(date.today().isoformat()))
        for title, number in repair:
            f.write("- {} ({}) rebinding requested\n".format(title, number))

    with open(os.path.join(batch, "rare_evaluation.txt"), "w", encoding="utf-8") as f:
        f.write("RARE BOOK EVALUATION REQUEST\n")
        for title, number in rare:
            f.write("{}: appraisal needed for {}\n".format(number, title))
        for title in unverified:
            f.write("NO-ID: catalog entry missing for {}\n".format(title))

    with open(os.path.join(batch, "new_arrivals.txt"), "w", encoding="utf-8") as f:
        for title, _number in sorted(shelf + rare):
            f.write(title + "\n")

    total = len(shelf) + len(repair) + len(rare)
    with open("annual_report.log", "a", encoding="utf-8") as f:
        f.write("{} {} volumes processed ({} shelved, {} repaired, {} rare)\n".format(
            date.today().isoformat(), total, len(shelf), len(repair), len(rare)))
    return total


def main():
    batch = os.environ.get("DONATION_BATCH", "batch_current")
    processed = ingest(batch)
    print("Ingested {} volumes from {}".format(processed, batch))


if __name__ == "__main__":
    main()

