def load_layout(path):
    layout = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            room, _, targets = line.strip().partition("->")
            room = room.strip()
            if room:
                layout[room] = [t.strip() for t in targets.split(",") if t.strip()]
    return layout


