def save_certificate(path, solvable, path_count, dead_end_count):
    with open(path, "w", encoding="utf-8") as f:
        f.write("solvable: {}\n".format("yes" if solvable else "no"))
        f.write("escape paths: {}\n".format(path_count))
        f.write("dead ends: {}\n".format(dead_end_count))


def blocked_rooms(puzzles, codes):
    return {room for room, code in puzzles.values() if code not in codes}


def find_paths(layout, blocked, start="start", exit_room="exit"):
    routes = []
    stack = [(start, [start])]
    while stack:
        room, route = stack.pop()
        if room == exit_room:
            routes.append(route)
            continue
        for nxt in layout.get(room, []):
            if nxt not in route and nxt not in blocked:
                stack.append((nxt, route + [nxt]))
    return routes


def validate(files):
    puzzles = load_puzzles(files[0])
    hints = load_hints(files[1])
    codes = load_codes(files[2])
    layout = load_layout(files[3])
