def read_temperature_curves(path):
    curves = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if line:
                batch_id, readings = line.split(",", 1)
                curves[batch_id] = [float(v) for v in readings.split(";") if v]
    return curves


def load_bean_origins(path):
    origins = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = [p.strip() for p in line.strip().split(",")]
            if len(parts) == 3:
                origins[parts[0]] = {"origin": parts[1], "grade": parts[2]}
    return origins


def parse_batch_metadata(path):
    metadata = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = [p.strip() for p in line.strip().split(",")]
            if len(parts) == 3:
                metadata[parts[0]] = {"target": float(parts[1]), "minimum_points": int(parts[2])}
    return metadata


def read_fault_logs(path):
    faults = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = [p.strip() for p in line.strip().split(",", 2)]
            if len(parts) == 3:
                faults.append({"machine": parts[0], "code": parts[1], "message": parts[2]})
    return faults


def write_approved_profiles(path, approved):
    with open(path, "w", encoding="utf-8") as f:
        for item in approved:
