def save_rejected_profiles(path, rejected):
    with open(path, "w", encoding="utf-8") as f:
        for item in rejected:
            f.write("{batch},{reason},{peak:.1f}\n".format(**item))


def log_maintenance_alerts(path, faults):
    with open(path, "w", encoding="utf-8") as f:
        for fault in faults:
            level = "CRITICAL" if fault["code"].startswith("E") else "NOTICE"
            f.write("%s %s [%s] %s\n" % (level, fault["machine"], fault["code"], fault["message"]))


def write_daily_summary(path, approved, rejected, faults):
    total = len(approved) + len(rejected)
    with open(path, "w", encoding="utf-8") as f:
        f.write("profiles analyzed: %d\n" % total)
        f.write("approved: %d\n" % len(approved))
        f.write("rejected: %d\n" % len(rejected))
        f.write("machine faults: %d\n" % len(faults))
        if approved:
            average = sum(item["peak"] for item in approved) / len(approved)
            f.write("average approved peak: %.1f\n" % average)


def profile(documents):
    curves_path, origins_path, metadata_path, faults_path = documents[:4]
    approved_path, rejected_path, alerts_path, summary_path = documents[4:]
    curves = read_temperature_curves(curves_path)
    origins = load_bean_origins(origins_path)
    metadata = parse_batch_metadata(metadata_path)
    faults = read_fault_logs(faults_path)
    approved, rejected = [], []
    for batch in sorted(curves):
        curve = curves[batch]
        spec = metadata.get(batch)
        bean = origins.get(batch)
        peak = max(curve) if curve else 0.0
        if spec is None or bean is None:
            rejected.append({"batch": batch, "reason": "incomplete-records", "peak": peak})
        elif len(curve) < spec["minimum_points"]:
            rejected.append({"batch": batch, "reason": "short-curve", "peak": peak})
        elif abs(peak - spec["target"]) > 5.0:
            rejected.append({"batch": batch, "reason": "temperature-deviation", "peak": peak})
        else:
            approved.append({"batch": batch, "origin": bean["origin"], "grade": bean["grade"], "peak": peak})
    write_approved_profiles(approved_path, approved)
    save_rejected_profiles(rejected_path, rejected)
    log_maintenance_alerts(alerts_path, faults)
    write_daily_summary(summary_path, approved, rejected, faults)
    return len(approved)


