            mod, name = line.split(":", 1)
            tracks.setdefault(mod.strip(), []).append(name.strip())
    f.close()
    return tracks


def read_script_warnings(path):
    warnings = {}
    f = open(path, "r", encoding="utf-8")
    for line in f:
        if ":" in line:
            mod, text = line.split(":", 1)
            warnings.setdefault(mod.strip(), []).append(text.strip())
    f.close()
    return warnings


def parse_missing_references(path):
    missing = {}
    f = open(path, "r", encoding="utf-8")
    for line in f:
        if "->" in line:
            mod, ref = line.split("->", 1)
            missing.setdefault(mod.strip(), []).append(ref.strip())
    f.close()
    return missing


def write_safe_modifications(path, safe_mods):
    f = open(path, "w", encoding="utf-8")
    for mod in sorted(safe_mods):
        f.write(mod + "\n")
    f.close()


def save_broken_modifications(path, broken_mods):
    f = open(path, "w", encoding="utf-8")
    for mod in sorted(broken_mods):
        f.write(mod + "\n")
    f.close()


def write_fix_recommendations(path, warnings, missing):
    f = open(path, "w", encoding="utf-8")
    for mod in sorted(set(warnings) | set(missing)):
        for text in warnings.get(mod, []):
            f.write("%s: review script warning '%s'\n" % (mod, text))
        for ref in missing.get(mod, []):
            f.write("%s: restore missing reference '%s'\n" % (mod, ref))
    f.close()


def write_review_summary(path, safe_mods, broken_mods, asset_counts):
    f = open(path, "w", encoding="utf-8")
    f.write("modifications reviewed: %d\n" % (len(safe_mods) + len(broken_mods)))
    f.write("safe: %d\n" % len(safe_mods))
    f.write("broken: %d\n" % len(broken_mods))
    for mod in sorted(asset_counts):
        f.write("%s uses %d assets\n" % (mod, asset_counts[mod]))
    f.close()


def lint(assets):
    textures = read_texture_list(assets["textures"])
    audio = load_audio_tracks(assets["audio"])
    warnings = read_script_warnings(assets["warnings"])
    missing = parse_missing_references(assets["missing_refs"])
    mods = set(textures) | set(audio) | set(warnings) | set(missing)
    asset_counts = {m: len(textures.get(m, [])) + len(audio.get(m, [])) for m in mods}
    safe_mods = [m for m in mods if not warnings.get(m) and not missing.get(m)]
    broken_mods = [m for m in mods if m not in safe_mods]
    write_safe_modifications(assets["safe_out"], safe_mods)
    save_broken_modifications(assets["broken_out"], broken_mods)
    write_fix_recommendations(assets["fixes_out"], warnings, missing)
    write_review_summary(assets["summary_out"], safe_mods, broken_mods, asset_counts)
    return len(safe_mods)

