    return items


def parse_dry_goods_list(path):
    items = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            items.update(_parse_stock_line(line, "dry"))
    return items


def _parse_stock_line(line, category):
    line = line.strip()
    if not line or line.startswith("#"):
        return {}
    name, qty, cost, spoiled = [part.strip() for part in line.split(",")]
    return {name: {"category": category, "qty": int(qty),
                   "cost": float(cost), "spoiled": int(spoiled)}}


def read_delivery_manifests(path):
    delivered = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if line and not line.startswith("#"):
                name, qty = [part.strip() for part in line.split(",")]
                delivered[name] = delivered.get(name, 0) + int(qty)
    return delivered


def save_reorder_list(path, names):
    with open(path, "w", encoding="utf-8") as f:
        for name in sorted(names):
            f.write("reorder,%s\n" % name)


def record_spoiled_items(path, spoiled):
