        for name, gap, value in sorted(rows):
            f.write("%s,%+d units,%+.2f\n" % (name, gap, value))


def write_budget_report(path, total, stock):
    with open(path, "w", encoding="utf-8") as f:
        f.write("items tracked: %d\n" % len(stock))
