        f.write("total discrepancy: %d\n" % total)


def audit(records):
    stock = load_meat_inventory(records["meat"])
    stock.update(load_vegetable_stock(records["vegetables"]))
    stock.update(parse_dry_goods_list(records["dry_goods"]))
    delivered = read_delivery_manifests(records["manifests"])

    reorder, spoiled, rows, total = [], {}, [], 0.0
    for name, data in stock.items():
        usable = data["qty"] - data["spoiled"]
        gap = delivered.get(name, data["qty"]) - data["qty"] - data["spoiled"]
        if gap:
            value = gap * data["cost"]
            rows.append((name, gap, value))
            total += value
        if data["spoiled"]:
            spoiled[name] = data["spoiled"]
        if usable < 10:
            reorder.append(name)

    save_reorder_list(records["reorder"], reorder)
    record_spoiled_items(records["spoiled"], spoiled)
    document_supplier_discrepancies(records["discrepancies"], rows)
    write_budget_report(records["budget"], int(round(total)), stock)
    return int(round(total))


