def read_rankings(path):
    players = []
    f = open(path, "r", encoding="utf-8")
    for line in f:
        parts = [p.strip() for p in line.split(",")]
        if len(parts) == 4 and parts[2].lstrip("-").isdigit():
            players.append({
                "name": parts[0],
                "position": parts[1].upper(),
                "rank": int(parts[2]),
                "projection": float(parts[3]),
            })
    f.close()
    players.sort(key=lambda p: p["rank"])
    return players


def read_injuries(path):
    statuses = {}
    f = open(path, "r", encoding="utf-8")
    for line in f:
        if "," in line:
            name, status = line.split(",", 1)
            statuses[name.strip()] = status.strip().lower()
    f.close()
    return statuses


def read_needs(path):
    needs = {}
    f = open(path, "r", encoding="utf-8")
    for line in f:
        parts = [p.strip() for p in line.split(",")]
        if len(parts) == 2 and parts[1].isdigit():
            needs[parts[0].upper()] = int(parts[1])
    f.close()
    return needs


def read_history(path):
    values = {}
    f = open(path, "r", encoding="utf-8")
    for line in f:
        parts = [p.strip() for p in line.split(",")]
        if len(parts) == 3:
            values.setdefault(parts[0].upper(), []).append(float(parts[2]))
    f.close()
    return {pos: sum(vals) / len(vals) for pos, vals in values.items()}


def score(player, injuries, needs, history):
    value = player["projection"] - player["rank"]
    value += 4.0 * needs.get(player["position"], 0)
    value += 0.1 * history.get(player["position"], 0.0)
    status = injuries.get(player["name"], "healthy")
    if status in ("out", "doubtful"):
        value -= 25.0
    elif status == "questionable":
        value -= 8.0
    return value


def write_top_picks(path, ranked):
    f = open(path, "w", encoding="utf-8")
    for position, (player, value) in enumerate(ranked[:5], start=1):
        f.write("%d. %s (%s) value=%.2f\n" % (position, player["name"], player["position"], value))
    f.close()


def write_sleepers(path, ranked):
    sleepers = [(p, v) for p, v in ranked if p["rank"] > 15 and v > 0]
    f = open(path, "w", encoding="utf-8")
    for player, value in sleepers[:5]:
        f.write("%s (%s) rank %d value=%.2f\n" % (player["name"], player["position"], player["rank"], value))
    f.close()


def write_busts(path, ranked, injuries):
    f = open(path, "w", encoding="utf-8")
    for player, value in ranked:
        status = injuries.get(player["name"], "healthy")
        if status != "healthy" or (player["rank"] <= 10 and value < 0):
            f.write("%s (%s): status=%s value=%.2f\n" % (player["name"], player["position"], status, value))
    f.close()


def write_strategy(path, ranked, needs, history):
    f = open(path, "w", encoding="utf-8")
    f.write("Players evaluated: %d\n" % len(ranked))
    for pos in sorted(needs):
        f.write("Need %s x%d, historical value %.2f\n" % (pos, needs[pos], history.get(pos, 0.0)))
    f.write("Opening plan: %s\n" % ", ".join(p["name"] for p, _ in ranked[:3]))
    f.close()


def analyze(rosters):
    rankings_path, injuries_path, needs_path, history_path = rosters[:4]
    top_path, sleeper_path, bust_path, strategy_path = rosters[4:]
    players = read_rankings(rankings_path)
    injuries = read_injuries(injuries_path)
    needs = read_needs(needs_path)
    history = read_history(history_path)
    ranked = sorted(((p, score(p, injuries, needs, history)) for p in players),
                    key=lambda item: item[1], reverse=True)
    write_top_picks(top_path, ranked)
    write_sleepers(sleeper_path, ranked)
    write_busts(bust_path, ranked, injuries)
    write_strategy(strategy_path, ranked, needs, history)
    return [player["name"] for player, _ in ranked[:3]]


def main():
    f = open("rankings.csv", "w", encoding="utf-8")
    f.write("Ada Speed,RB,1,290\nBo Arm,QB,2,310\nCy Hands,WR,3,250\n")
    f.write("Dee Leg,RB,12,210\nEli Grip,TE,18,180\nFin Foot,WR,25,205\n")
    f.close()
    f = open("injuries.csv", "w", encoding="utf-8")
    f.write("Cy Hands,questionable\nDee Leg,out\n")
    f.close()
    f = open("needs.csv", "w", encoding="utf-8")
    f.write("RB,2\nWR,1\nTE,1\n")
    f.close()
    f = open("history.csv", "w", encoding="utf-8")
    f.write("RB,2022,88\nRB,2023,91\nWR,2023,80\nQB,2023,70\nTE,2023,55\n")
    f.close()
    picks = analyze(("rankings.csv", "injuries.csv", "needs.csv", "history.csv",
                     "top_picks.txt", "sleepers.txt", "busts.txt", "strategy.txt"))
    print("Top three:", ", ".join(picks))


if __name__ == "__main__":
