def read_acidity(path):
    levels = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if line.strip():
                tank, value = line.split()
                levels[tank] = float(value)
    return levels


def load_temperatures(path):
    logs = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = line.split()
            if parts:
                logs[parts[0]] = [float(v) for v in parts[1:]]
    return logs


def parse_feeding(path):
    schedules = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if ":" in line:
                tank, times = line.split(":", 1)
                schedules[tank.strip()] = [t.strip() for t in times.split(",") if t.strip()]
    return schedules


def read_dosages(path):
    doses = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = line.split()
            if parts:
                doses[parts[0]] = float(parts[1])
    return doses


def save_healthy(path, names):
    with open(path, "w", encoding="utf-8") as f:
        for name in sorted(names):
            f.write(name + "\n")


def write_warnings(path, flags):
    with open(path, "w", encoding="utf-8") as f:
        for tank, reason in flags:
            f.write("{0}\t{1}\n".format(tank, reason))


def record_dead_fish(path, entries):
    with open(path, "a", encoding="utf-8") as f:
        for tank, count in entries:
            f.write("{0} lost {1} fish\n".format(tank, count))


def output_status(path, summary):
    with open(path, "w", encoding="utf-8") as f:
        for key in ("tanks", "healthy", "warnings", "critical"):
            f.write("{0}={1}\n".format(key, summary[key]))
        f.write("status={0}\n".format("ALERT" if summary["critical"] else "STABLE"))


def monitor(tanks):
    acid_path, temp_path, feed_path, dose_path = tanks[:4]
    healthy_path, warn_path, dead_path, status_path = tanks[4:]
    acidity = read_acidity(acid_path)
    temperatures = load_temperatures(temp_path)
    schedules = parse_feeding(feed_path)
    dosages = read_dosages(dose_path)
    healthy, flags, dead = [], [], []
    critical = 0
    for tank in sorted(acidity):
        ph = acidity[tank]
        readings = temperatures.get(tank, [])
        average = sum(readings) / len(readings) if readings else 0.0
        problems = []
        if ph < 6.5:
            problems.append("high acidity ({0:.2f} pH)".format(ph))
            critical += 1
        if readings and not 18.0 <= average <= 30.0:
            problems.append("temperature {0:.1f}C".format(average))
        if not schedules.get(tank):
            problems.append("no feeding schedule")
        if dosages.get(tank, 0.0) > 5.0:
            problems.append("medicine overdose {0:.1f}mg".format(dosages[tank]))
        if ph < 5.8 or average > 33.0:
            dead.append((tank, len(readings)))
        if problems:
            flags.extend((tank, reason) for reason in problems)
        else:
            healthy.append(tank)
    save_healthy(healthy_path, healthy)
    write_warnings(warn_path, flags)
    record_dead_fish(dead_path, dead)
    output_status(status_path, {"tanks": len(acidity), "healthy": len(healthy),
                                "warnings": len(flags), "critical": critical})
    return critical


