        out.write("tank1: 08:00, 18:00\ntank2: 09:00\ntank3: 07:30\ntank4: 08:15\n")
    with open(paths[3], "w", encoding="utf-8") as out:
        out.write("tank1 2.0\ntank2 0.0\ntank3 1.5\ntank4 0.5\n")
    print(monitor(paths))

