    with open(path, "w") as f:
        total = 0.0
        for plot, (crop, maturity, age) in sorted(catalog.items()):
            base = 12.0 * min(1.0, age / float(maturity))
            projected = base * (1.0 + sunlight.get(plot, 0.0) / 20.0)
            projected -= pest_load.get(plot, 0) * 0.8
            projected = max(0.0, projected)
            total += projected
            f.write("{} {} {:.2f}kg\n".format(plot, crop, projected))
