WAIT_TIMES_FILE = "ride_wait_times.csv"
PARADE_FILE = "parade_schedule.csv"
TICKET_FILE = "ticket_sales.csv"
WEATHER_FILE = "hourly_weather.csv"
BOTTLENECK_FILE = "bottleneck_warnings.txt"
UNDERUSED_FILE = "underutilized_areas.txt"
REROUTE_FILE = "crowd_rerouting_plans.txt"
METRICS_FILE = "daily_crowd_metrics.txt"


def read_wait_times(path):
    waits = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            zone, ride, minutes = [part.strip() for part in line.split(",")]
            waits.setdefault(zone, []).append((ride, int(minutes)))
    return waits


def read_parade_schedule(path):
    schedule = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            start, zone = [part.strip() for part in line.split(",")]
            schedule.setdefault(zone, []).append(start)
    return schedule


def parse_ticket_sales(path):
    sales = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            hour, tickets = [part.strip() for part in line.split(",")]
            sales[int(hour)] = sales.get(int(hour), 0) + int(tickets)
    return sales


def read_weather(path):
    conditions = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            hour, condition = [part.strip() for part in line.split(",")]
            conditions[int(hour)] = condition.lower()
    return conditions


def write_bottleneck_warnings(path, bottlenecks):
    with open(path, "w", encoding="utf-8") as f:
        for zone, worst_ride, minutes in bottlenecks:
            f.write("WARNING {0}: {1} at {2} min\n".format(zone, worst_ride, minutes))


def write_underutilized_suggestions(path, quiet_zones):
    with open(path, "w", encoding="utf-8") as f:
        for zone, average in quiet_zones:
            f.write("{0} averages {1:.1f} min - promote street entertainment\n".format(zone, average))


def log_rerouting_plans(path, plans):
    with open(path, "w", encoding="utf-8") as f:
        for source, target, note in plans:
            f.write("Reroute {0} -> {1} ({2})\n".format(source, target, note))


def write_daily_metrics(path, metrics):
    with open(path, "w", encoding="utf-8") as f:
        for name in sorted(metrics):
            f.write("{0}={1}\n".format(name, metrics[name]))


def control(zones):
    waits = read_wait_times(WAIT_TIMES_FILE)
    parades = read_parade_schedule(PARADE_FILE)
    sales = parse_ticket_sales(TICKET_FILE)
    weather = read_weather(WEATHER_FILE)

    bottlenecks = []
    quiet_zones = []
    peak_wait = 0
    for zone in zones:
        rides = waits.get(zone, [])
        if not rides:
            continue
        minutes = [entry[1] for entry in rides]
        average = sum(minutes) / len(minutes)
        worst_ride, worst = max(rides, key=lambda entry: entry[1])
        peak_wait = max(peak_wait, worst)
        if average >= 40:
            bottlenecks.append((zone, worst_ride, worst))
        elif average < 15:
            quiet_zones.append((zone, average))

    write_bottleneck_warnings(BOTTLENECK_FILE, bottlenecks)
    write_underutilized_suggestions(UNDERUSED_FILE, quiet_zones)

    plans = []
    for zone, _ride, _worst in bottlenecks:
        for target, _average in quiet_zones:
            if target in parades:
                note = "avoid parade at " + ", ".join(parades[target])
            else:
                note = "open walkway"
            plans.append((zone, target, note))
    log_rerouting_plans(REROUTE_FILE, plans)

    wet_hours = [hour for hour, condition in weather.items() if "rain" in condition]
    metrics = {
        "total_tickets": sum(sales.values()),
        "busiest_hour": max(sales, key=lambda hour: sales[hour]) if sales else "n/a",
        "wet_hours": len(wet_hours),
        "bottleneck_zones": len(bottlenecks),
        "underutilized_zones": len(quiet_zones),
        "peak_wait_minutes": peak_wait,
    }
    write_daily_metrics(METRICS_FILE, metrics)
    return peak_wait


if __name__ == "__main__":
    park_zones = ["Fantasy Hill", "Rocket Row", "Lagoon Walk", "Old Town"]
    print("Peak wait time:", control(park_zones))

