        peak_wait = max(peak_wait, worst)
        if average >= 40:
            bottlenecks.append((zone, worst_ride, worst))
        elif average < 15:
            quiet_zones.append((zone, average))

    write_bottleneck_warnings(BOTTLENECK_FILE, bottlenecks)
    write_underutilized_suggestions(UNDERUSED_FILE, quiet_zones)

    plans = []
    for zone, _ride, _worst in bottlenecks:
        for target, _average in quiet_zones:
            if target in parades:
                note = "avoid parade at " + ", ".join(parades[target])
            else:
                note = "open walkway"
            plans.append((zone, target, note))
    log_rerouting_plans(REROUTE_FILE, plans)

    wet_hours = [hour for hour, condition in weather.items() if "rain" in condition]
    metrics = {
        "total_tickets": sum(sales.values()),
        "busiest_hour": max(sales, key=lambda hour: sales[hour]) if sales else "n/a",
        "wet_hours": len(wet_hours),
        "bottleneck_zones": len(bottlenecks),
        "underutilized_zones": len(quiet_zones),
        "peak_wait_minutes": peak_wait,
    }
    write_daily_metrics(METRICS_FILE, metrics)
    return peak_wait


if __name__ == "__main__":
    park_zones = ["Fantasy Hill", "Rocket Row", "Lagoon Walk", "Old Town"]
    print("Peak wait time:", control(park_zones))

