def read_missing_parts(path):
    items = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            row = line.strip()
            if row and not row.startswith("#"):
                name, qty, price = row.split(",")
                items.append((name.strip(), int(qty), float(price)))
    return items


def load_engine_specs(path):
    specs = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if "=" in line:
                key, value = line.split("=", 1)
                specs[key.strip().lower()] = value.strip()
    return specs


def parse_paint_codes(path):
    colors = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            fields = line.split()
            if len(fields) >= 2:
                colors[fields[0]] = " ".join(fields[1:])
    return colors


def read_manual(path):
    lines = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            text = line.strip()
            if text:
                lines.append(text)
    return lines


def save_order_sheet(path, items):
    with open(path, "w", encoding="utf-8") as f:
        f.write("PART\tQTY\tSUBTOTAL\n")
        for name, qty, price in items:
            f.write("%s\t%d\t%.2f\n" % (name, qty, qty * price))
    return sum(qty * price for _, qty, price in items)


def write_assembly_steps(path, manual_lines, colors):
    with open(path, "w", encoding="utf-8") as f:
        for number, line in enumerate(manual_lines, start=1):
            text = line
            for code, name in colors.items():
                text = text.replace(code, "%s (%s)" % (code, name))
            f.write("Step %d: %s\n" % (number, text))
    return len(manual_lines)


def document_mismatches(path, specs, manual_lines):
    required = {}
    for line in manual_lines:
        if line.lower().startswith("spec:") and "=" in line:
            key, value = line[5:].split("=", 1)
            required[key.strip().lower()] = value.strip()
    problems = []
    for key, value in sorted(required.items()):
        found = specs.get(key)
        if found != value:
            problems.append("%s: manual=%s engine=%s" % (key, value, found or "absent"))
    with open(path, "w", encoding="utf-8") as f:
        for problem in problems:
            f.write(problem + "\n")
    return problems


def output_budget(path, parts_cost, labour_cost, total):
    with open(path, "w", encoding="utf-8") as f:
        f.write("Parts    : %.2f\n" % parts_cost)
        f.write("Labour   : %.2f\n" % labour_cost)
        f.write("Estimate : %.2f\n" % total)


def restore(parts):
    manifest, engine, paint, manual, order, steps, mismatch, budget = parts
    items = read_missing_parts(manifest)
    specs = load_engine_specs(engine)
    colors = parse_paint_codes(paint)
    manual_lines = read_manual(manual)
    parts_cost = save_order_sheet(order, items)
    step_count = write_assembly_steps(steps, manual_lines, colors)
    problems = document_mismatches(mismatch, specs, manual_lines)
    if items or problems:
        labour_cost = 120.0 * step_count + 800.0 * len(problems)
        total = parts_cost + labour_cost
    else:
        labour_cost = 5000.0 - parts_cost
        total = 5000.0
    output_budget(budget, parts_cost, labour_cost, total)
    return total

