                name, qty, unit = (part.strip() for part in line.split(","))
                recipe.append((name, float(qty), unit))
    return recipe


def load_daily_orders(path):
    orders = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if line.strip():
                cake, count = (part.strip() for part in line.split(","))
                orders[cake] = orders.get(cake, 0) + int(count)
    return orders


def load_substitutions(path):
    subs = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if line.strip():
                original, replacement, allergen = (p.strip() for p in line.split(","))
                subs[original] = (replacement, allergen)
    return subs


def load_pan_sizes(path):
    pans = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if line.strip():
                cake, diameter, minutes = (p.strip() for p in line.split(","))
                pans[cake] = (float(diameter), float(minutes))
    return pans


def save_shopping_list(path, totals):
    with open(path, "w", encoding="utf-8") as f:
        for name, qty, unit in totals:
            f.write("{}: {:.2f} {}\n".format(name, qty, unit))


def save_allergy_warnings(path, warnings):
    with open(path, "w", encoding="utf-8") as f:
        for original, replacement, allergen in warnings:
            f.write("{} contains {} - replace with {}\n".format(original, allergen, replacement))


def log_adjusted_bake_times(path, bake_rows):
    with open(path, "a", encoding="utf-8") as f:
        for cake, diameter, minutes in bake_rows:
            f.write("{} ({:.0f} cm pan): {:.0f} min\n".format(cake, diameter, minutes))


def save_oven_schedule(path, schedule):
    with open(path, "w", encoding="utf-8") as f:
        for start, cake, minutes in schedule:
            f.write("{:02d}:{:02d} {} for {:.0f} min\n".format(start // 60, start % 60, cake, minutes))


def scale(orders):
    ing_path, order_path, sub_path, pan_path, list_path, allergy_path, bake_path, oven_path = orders
    recipe = load_base_ingredients(ing_path)
    daily = load_daily_orders(order_path)
    subs = load_substitutions(sub_path)
    pans = load_pan_sizes(pan_path)
    cakes = sum(daily.values())

    totals = []
    warnings = []
    for name, qty, unit in recipe:
        if name in subs:
            replacement, allergen = subs[name]
            warnings.append((name, replacement, allergen))
            name = replacement
        totals.append((name, qty * cakes, unit))

    bake_rows = []
    for cake, count in sorted(daily.items()):
        diameter, base_minutes = pans.get(cake, (20.0, 30.0))
        minutes = round(base_minutes * (diameter / 20.0) ** 0.5)
        for _ in range(count):
            bake_rows.append((cake, diameter, minutes))

    schedule = []
    clock = 6 * 60
    for cake, _diameter, minutes in bake_rows:
        schedule.append((clock, cake, minutes))
        clock += int(minutes) + 10

    save_shopping_list(list_path, totals)
    save_allergy_warnings(allergy_path, warnings)
    log_adjusted_bake_times(bake_path, bake_rows)
    save_oven_schedule(oven_path, schedule)

    return int(round(sum(qty for name, qty, _u in totals if name == "eggs")))


if __name__ == "__main__":
    print(scale(sys.argv[1:9]))

