import json
from collections import defaultdict


def read_collar_positions(path="collar_positions.csv"):
    positions = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = line.strip().split(",")
            if len(parts) == 4:
                collar_id, lat, lon, status = parts
                positions[collar_id] = {
                    "lat": float(lat),
                    "lon": float(lon),
                    "status": status.lower(),
                }
    return positions


def read_camera_timestamps(path="camera_timestamps.txt"):
    sightings = defaultdict(list)
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            fields = line.split()
            if len(fields) >= 3:
                sightings[fields[1]].append((fields[0], fields[2]))
    return sightings


def parse_trap_locations(path="live_traps.json"):
    with open(path, "r", encoding="utf-8") as f:
        raw = json.load(f)
    return [t for t in raw.get("traps", []) if t.get("armed")]


def read_weather_events(path="weather_events.log"):
    events = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if "|" in line:
                date, kind, severity = (p.strip() for p in line.split("|", 2))
                events.append({"date": date, "kind": kind, "severity": severity})
    return events


def save_migration_paths(paths, path="migration_paths.json"):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(paths, f, indent=2, sort_keys=True)


def write_density_heatmap(grid, path="density_heatmap.csv"):
    with open(path, "w", encoding="utf-8") as f:
        f.write("cell_lat,cell_lon,count\n")
        for (cell_lat, cell_lon), count in sorted(grid.items()):
            f.write(f"{cell_lat},{cell_lon},{count}\n")


def document_broken_equipment(broken, path="broken_equipment.txt"):
    with open(path, "w", encoding="utf-8") as f:
        for collar_id, status in sorted(broken):
            f.write(f"collar {collar_id}: {status}\n")


def write_ecosystem_report(summary, path="ecosystem_health.txt"):
    with open(path, "w", encoding="utf-8") as f:
        for key in ("active_collars", "broken_collars", "species_seen",
                    "armed_traps", "severe_weather_events"):
            f.write(f"{key}: {summary[key]}\n")


def locate(animals):
    positions = read_collar_positions()
    sightings = read_camera_timestamps()
    traps = parse_trap_locations()
    weather = read_weather_events()

    tracked = {a: positions[a] for a in animals if a in positions}
    active = [cid for cid, p in tracked.items() if p["status"] == "active"]
    broken = [(cid, p["status"]) for cid, p in tracked.items()
              if p["status"] != "active"]

    grid = defaultdict(int)
    for p in tracked.values():
        grid[(round(p["lat"], 1), round(p["lon"], 1))] += 1

    routes = {}
    for cid in active:
        stops = sorted(sightings.get(cid, []))
        routes[cid] = [{"time": t, "camera": cam} for t, cam in stops]

    save_migration_paths(routes)
    write_density_heatmap(grid)
    document_broken_equipment(broken)
    write_ecosystem_report({
        "active_collars": len(active),
        "broken_collars": len(broken),
        "species_seen": len(sightings),
        "armed_traps": len(traps),
        "severe_weather_events": sum(1 for e in weather
                                     if e["severity"] == "severe"),
    })
    return len(active)


def main():
    with open("reserve_animals.txt", "r", encoding="utf-8") as f:
        animals = [line.strip() for line in f if line.strip()]
    print(f"active collars: {locate(animals)}")


if __name__ == "__main__":
    main()

