import sys


def read_hull_blueprints(path):
    compartments = []
    with open(path, "r", encoding="utf-8") as hull_file:
        for line in hull_file:
            parts = line.split()
            if len(parts) == 3:
                compartments.append({"name": parts[0], "length": float(parts[1]), "thickness": float(parts[2])})
    return compartments


def load_pressure_limits(path):
    limits = []
    with open(path, "r", encoding="utf-8") as pressure_file:
        for line in pressure_file:
            parts = line.split()
            if len(parts) == 2:
                limits.append((float(parts[0]), float(parts[1])))
    return limits


def parse_crew_requirements(path):
    crew = {}
    with open(path, "r", encoding="utf-8") as crew_file:
        for line in crew_file:
            role, _, count = line.partition(":")
            if count.strip():
                crew[role.strip()] = int(count)
    return crew


def read_emergency_protocols(path):
    with open(path, "r", encoding="utf-8") as protocol_file:
        protocols = [line.strip() for line in protocol_file if line.strip()]
    return protocols


def write_hatch_locations(path, locations):
    with open(path, "w", encoding="utf-8") as hatch_file:
        for index, position in enumerate(locations, start=1):
            hatch_file.write("hatch {0} at {1:.2f} m from bow\n".format(index, position))


def write_weakness_warnings(path, warnings):
    with open(path, "w", encoding="utf-8") as warning_file:
        if not warnings:
            warning_file.write("no structural weaknesses detected\n")
        for name, thickness, required in warnings:
            warning_file.write("{0}: {1:.1f} mm hull, {2:.1f} mm required\n".format(name, thickness, required))


def log_evacuation_times(path, times):
    with open(path, "a", encoding="utf-8") as evac_file:
        for role in sorted(times):
            evac_file.write("{0}\t{1:.1f} min\n".format(role, times[role]))


def write_safety_rating(path, rating, grade):
    with open(path, "w", encoding="utf-8") as rating_file:
        rating_file.write("score: {0:.1f}\ngrade: {1}\n".format(rating, grade))


def design(blueprints):
    if len(blueprints) != 8:
        raise ValueError("design() needs exactly eight file paths")
    hull_p, pressure_p, crew_p, protocol_p, hatch_p, warning_p, evac_p, rating_p = blueprints
    compartments = read_hull_blueprints(hull_p)
    limits = load_pressure_limits(pressure_p)
    crew = parse_crew_requirements(crew_p)
    protocols = read_emergency_protocols(protocol_p)

    total_length = sum(c["length"] for c in compartments)
    total_crew = sum(crew.values())
    required_thickness = max(pressure for _, pressure in limits) * 1.5
    warnings = [(c["name"], c["thickness"], required_thickness)
                for c in compartments if c["thickness"] < required_thickness]
    if total_length >= 80.0 or total_crew >= 60:
        hatches = 4
    elif total_crew >= 30:
        hatches = 3
    else:
        hatches = 2
    locations = [total_length * (i + 0.5) / hatches for i in range(hatches)]
    times = {role: count / (hatches * 2.5) + 0.5 * len(protocols) for role, count in crew.items()}
    score = max(0.0, 100.0 - 8.0 * len(warnings) - max(0.0, total_crew - 10.0 * hatches))
    grade = "A" if score >= 90 else "B" if score >= 75 else "C" if score >= 60 else "D"

    write_hatch_locations(hatch_p, locations)
    write_weakness_warnings(warning_p, warnings)
    log_evacuation_times(evac_p, times)
    write_safety_rating(rating_p, score, grade)
    return hatches


if __name__ == "__main__":
    print("required escape hatches:", design(sys.argv[1:9]))

