import os


def read_min_score(path):
    with open(path, "r", encoding="utf-8") as f:
        text = f.read().strip()
    if not text:
        raise ValueError("parameters.txt does not contain a minimum score")
    return float(text.split()[0])


def read_applicants(path):
    names = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            name = line.strip()
            if name:
                names.append(name)
    return names


def read_scores(path):
    scores = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            parts = line.split(",")
            if len(parts) < 2:
                raise ValueError("malformed line in scores.csv: " + line)
            scores[parts[0].strip()] = float(parts[1].strip())
    return scores


def read_interviews(path):
    results = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = line.split()
            if len(parts) < 2:
                continue
            results[" ".join(parts[:-1])] = parts[-1].strip().lower()
    return results


def write_names(path, names):
    with open(path, "w", encoding="utf-8") as f:
        for name in names:
            f.write(name + "\n")


def write_statistics(path, admitted, denied):
    with open(path, "w", encoding="utf-8") as f:
        f.write("admitted: {}\n".format(len(admitted)))
        f.write("denied: {}\n".format(len(denied)))
        f.write("total: {}\n".format(len(admitted) + len(denied)))


def screen(folder):
    minimum = read_min_score(os.path.join(folder, "parameters.txt"))
    applicants = read_applicants(os.path.join(folder, "applicants.txt"))
    scores = read_scores(os.path.join(folder, "scores.csv"))
    interviews = read_interviews(os.path.join(folder, "interviews.txt"))

    admitted, denied = [], []
    for name in applicants:
        score = scores.get(name)
        verdict = interviews.get(name)
        if score is not None and score >= minimum and verdict == "pass":
            admitted.append(name)
        else:
            denied.append(name)

    write_names(os.path.join(folder, "admitted.txt"), admitted)
    write_names(os.path.join(folder, "denied.txt"), denied)
    write_statistics(os.path.join(folder, "statistics.txt"), admitted, denied)
    with open(os.path.join(folder, "status.log"), "w", encoding="utf-8") as f:
        f.write("finished\n")
    return admitted, denied


if __name__ == "__main__":
    import sys

    target = sys.argv[1] if len(sys.argv) > 1 else "."
    ok, no = screen(target)
    print("admitted {} / denied {}".format(len(ok), len(no)))

