import csv
import os


def read_drivers(path):
    drivers = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            name, _, capacity = line.rpartition(",")
            drivers.append((name.strip(), int(capacity.strip())))
    return drivers


def read_packages(path):
    packages = []
    with open(path, "r", encoding="utf-8", newline="") as f:
        for row in csv.reader(f):
            if len(row) >= 2:
                packages.append((row[0].strip(), row[1].strip()))
    return packages


def read_zones(path):
    with open(path, "r", encoding="utf-8") as f:
        return {line.strip() for line in f if line.strip()}


def read_priorities(path):
    with open(path, "r", encoding="utf-8", newline="") as f:
        return {row[0].strip() for row in csv.reader(f) if row and row[0].strip()}


def assign(drivers, packages, zones, priorities):
    routes = {name: [] for name, _ in drivers}
    remaining = {name: cap for name, cap in drivers}
    order = [p for p in packages if p[0] in priorities] + \
            [p for p in packages if p[0] not in priorities]
    unassigned = []
    for pid, zone in order:
        if zone not in zones:
            unassigned.append((pid, zone, "inactive zone"))
            continue
        for name, _ in drivers:
            if remaining[name] > 0:
                routes[name].append(pid)
                remaining[name] -= 1
                break
        else:
            unassigned.append((pid, zone, "no capacity"))
    return routes, unassigned


def dispatch(folder):
    drivers = read_drivers(os.path.join(folder, "drivers.txt"))
    packages = read_packages(os.path.join(folder, "packages.csv"))
    zones = read_zones(os.path.join(folder, "zones.txt"))
    priorities = read_priorities(os.path.join(folder, "priorities.csv"))
    routes, unassigned = assign(drivers, packages, zones, priorities)

    with open(os.path.join(folder, "routes.csv"), "w", encoding="utf-8", newline="") as f:
        writer = csv.writer(f)
        for name, _ in drivers:
            for pid in routes[name]:
                writer.writerow([name, pid])

    with open(os.path.join(folder, "unassigned.csv"), "w", encoding="utf-8", newline="") as f:
        writer = csv.writer(f)
        for pid, zone, reason in unassigned:
            writer.writerow([pid, zone, reason])

    with open(os.path.join(folder, "inactive.txt"), "w", encoding="utf-8") as f:
        for name, _ in drivers:
            if not routes[name]:
                f.write(name + "\n")

    dispatched = sum(len(pids) for pids in routes.values())
    with open(os.path.join(folder, "audit.log"), "w", encoding="utf-8") as f:
        f.write("dispatched=%d\n" % dispatched)
        f.write("unassigned=%d\n" % len(unassigned))
    return dispatched


if __name__ == "__main__":
    import sys
    target = sys.argv[1] if len(sys.argv) > 1 else "."
    print("dispatched %d packages" % dispatch(target))

