import csv
import os


def load_fleet(path):
    fleet = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = line.split()
            if len(parts) == 2:
                fleet[parts[0]] = float(parts[1])
    return fleet


def load_reservations(path):
    reservations = []
    with open(path, "r", encoding="utf-8", newline="") as f:
        for row in csv.reader(f):
            if len(row) == 3:
                reservations.append((row[0].strip(), row[1].strip(), int(row[2])))
    return reservations


def load_damages(path):
    damaged = set()
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            reg = line.strip()
            if reg:
                damaged.add(reg)
    return damaged


def load_discounts(path):
    discounts = {}
    with open(path, "r", encoding="utf-8", newline="") as f:
        for row in csv.reader(f):
            if len(row) == 2:
                discounts[row[0].strip()] = float(row[1])
    return discounts


def price_for(rate, days, discount):
    return round(rate * days * (1.0 - discount / 100.0), 2)


def process(directory):
    fleet = load_fleet(os.path.join(directory, "fleet.txt"))
    reservations = load_reservations(os.path.join(directory, "reservations.csv"))
    damaged = load_damages(os.path.join(directory, "damages.txt"))
    discounts = load_discounts(os.path.join(directory, "discounts.csv"))

    invoices = []
    grounded = []
    reserved = set()
    total = 0.0

    for reg, customer, days in reservations:
        if reg not in fleet:
            continue
        if reg in damaged:
            grounded.append((customer, reg))
            continue
        reserved.add(reg)
        amount = price_for(fleet[reg], days, discounts.get(customer, 0.0))
        invoices.append((customer, amount))
        total += amount

    with open(os.path.join(directory, "invoices.csv"), "w", encoding="utf-8", newline="") as f:
        writer = csv.writer(f)
        for customer, amount in invoices:
            writer.writerow([customer, "%.2f" % amount])

    with open(os.path.join(directory, "grounded.txt"), "w", encoding="utf-8") as f:
        for customer, reg in grounded:
            f.write("%s %s cancelled: vehicle under repair\n" % (customer, reg))

    with open(os.path.join(directory, "revenue.txt"), "w", encoding="utf-8") as f:
        f.write("Total expected income: %.2f\n" % round(total, 2))

    with open(os.path.join(directory, "availability.csv"), "w", encoding="utf-8", newline="") as f:
        writer = csv.writer(f)
        for reg in sorted(reg for reg in fleet if reg not in reserved):
            writer.writerow([reg, "%.2f" % fleet[reg]])

    return round(total, 2)


if __name__ == "__main__":
    import sys

    print(process(sys.argv[1] if len(sys.argv) > 1 else "."))

