import csv
import os


def load_teams(path):
    teams = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            name = line.strip()
            if name:
                teams.append(name)
    return teams


def load_matches(path):
    matches = []
    with open(path, "r", encoding="utf-8", newline="") as f:
        for row in csv.reader(f):
            if len(row) == 4:
                matches.append((row[0].strip(), row[1].strip(), int(row[2]), int(row[3])))
    return matches


def load_penalties(path):
    penalties = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = line.replace(",", " ").split()
            if len(parts) >= 2:
                penalties[" ".join(parts[:-1])] = penalties.get(" ".join(parts[:-1]), 0) + int(parts[-1])
    return penalties


def load_bonuses(path):
    bonuses = {}
    with open(path, "r", encoding="utf-8", newline="") as f:
        for row in csv.reader(f):
            if len(row) >= 2:
                team = row[0].strip()
                bonuses[team] = bonuses.get(team, 0) + int(row[1])
    return bonuses


def match_points(teams, matches):
    points = {team: 0 for team in teams}
    for home, away, hs, away_score in matches:
        if home in points and away in points:
            if hs > away_score:
                points[home] += 3
            elif away_score > hs:
                points[away] += 3
            else:
                points[home] += 1
                points[away] += 1
    return points


def track(folder):
    teams = load_teams(os.path.join(folder, "teams.txt"))
    matches = load_matches(os.path.join(folder, "matches.csv"))
    penalties = load_penalties(os.path.join(folder, "penalties.txt"))
    bonuses = load_bonuses(os.path.join(folder, "bonuses.csv"))

    earned = match_points(teams, matches)
    totals = {}
    for team in teams:
        totals[team] = earned[team] + bonuses.get(team, 0) - penalties.get(team, 0)

    ranked = sorted(totals.items(), key=lambda item: (-item[1], item[0]))
    with open(os.path.join(folder, "standings.csv"), "w", encoding="utf-8", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["team", "points"])
        writer.writerows(ranked)

    disqualified = [team for team, total in ranked if total < 0]
    with open(os.path.join(folder, "disqualified.txt"), "w", encoding="utf-8") as f:
        for team in disqualified:
            f.write(team + "\n")

    with open(os.path.join(folder, "highlights.txt"), "w", encoding="utf-8") as f:
        for team, extra in sorted(bonuses.items(), key=lambda item: (-item[1], item[0])):
            if team in totals and extra > 0:
                f.write("{0} +{1}\n".format(team, extra))

    eligible = [(team, total) for team, total in ranked if total >= 0]
    with open(os.path.join(folder, "final.log"), "w", encoding="utf-8") as f:
        if eligible:
            f.write("winner: {0} ({1} points)\n".format(eligible[0][0], eligible[0][1]))
        else:
            f.write("winner: none\n")
    return ranked


if __name__ == "__main__":
    import sys

    for team, total in track(sys.argv[1] if len(sys.argv) > 1 else "."):
        print(team, total)

