import os

VIRAL_THRESHOLD = 1000


def load_keywords(path):
    keywords = []
    with open(os.path.join(path, "keywords.txt"), "r", encoding="utf-8") as f:
        for line in f:
            word = line.strip().lower()
            if word:
                keywords.append(word)
    return keywords


def load_banned(path):
    banned = set()
    with open(os.path.join(path, "banned.txt"), "r", encoding="utf-8") as f:
        for line in f:
            name = line.strip().lower()
            if name:
                banned.add(name)
    return banned


def load_authors(path):
    authors = {}
    with open(os.path.join(path, "authors.csv"), "r", encoding="utf-8", newline="") as f:
        for row in csv.reader(f):
            if len(row) >= 2:
                authors[row[0].strip()] = row[1].strip()
    return authors


def load_posts(path):
    posts = []
    with open(os.path.join(path, "posts.csv"), "r", encoding="utf-8", newline="") as f:
        for row in csv.reader(f):
            if len(row) < 3:
                continue
            try:
                likes = int(row[2].strip())
            except ValueError:
                continue
            posts.append((row[0].strip(), row[1], likes))
    return posts


def write_trends(path, trends, keywords):
    with open(os.path.join(path, "trends.csv"), "w", encoding="utf-8", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["keyword", "total_likes"])
        for word in keywords:
            writer.writerow([word, trends[word]])


def write_viral(path, viral):
    with open(os.path.join(path, "viral.txt"), "w", encoding="utf-8") as f:
        for post_id in viral:
            f.write(post_id + "\n")


def write_contributors(path, contributors):
    with open(os.path.join(path, "contributors.csv"), "w", encoding="utf-8", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["author", "accepted_posts"])
        for author in sorted(contributors):
            writer.writerow([author, contributors[author]])


