    banned = load_banned(path)
    authors = load_authors(path)
    posts = load_posts(path)

    trends = {word: 0 for word in keywords}
    contributors = {}
    viral = []
    processed = 0

    for post_id, text, likes in posts:
        author = authors.get(post_id, "")
        if not author or author.lower() in banned:
