import os


def read_screens(folder):
    capacities = {}
    with open(os.path.join(folder, "screens.txt")) as f:
        for line in f:
            parts = line.split()
            if len(parts) == 2:
                capacities[parts[0]] = int(parts[1])
    return capacities


def read_pricing(folder):
    prices = {}
    with open(os.path.join(folder, "pricing.csv")) as f:
        for line in f:
            fields = [field.strip() for field in line.split(",")]
            if len(fields) == 2 and fields[1].replace(".", "", 1).isdigit():
                prices[fields[0]] = float(fields[1])
    return prices


def read_sales(folder):
    sales = {}
    with open(os.path.join(folder, "sales.csv")) as f:
        for line in f:
            fields = [field.strip() for field in line.split(",")]
            if len(fields) == 3 and fields[2].isdigit():
                sales.setdefault(fields[0], []).append((fields[1], int(fields[2])))
    return sales


def read_refunds(folder):
    refunds = {}
    with open(os.path.join(folder, "refunds.txt")) as f:
        for line in f:
            parts = line.split()
            if len(parts) == 2:
                refunds[parts[0]] = refunds.get(parts[0], 0) + int(parts[1])
    return refunds


def audit(folder):
    capacities = read_screens(folder)
    prices = read_pricing(folder)
    sales = read_sales(folder)
    refunds = read_refunds(folder)

    rows = []
    oversold = []
    popular = []
    total = 0.0
    for screen in sorted(capacities, key=lambda s: (len(s), s)):
        capacity = capacities[screen]
        entries = sales.get(screen, [])
        net = sum(count for _, count in entries) - refunds.get(screen, 0)
        if net > capacity:
            oversold.append((screen, net, capacity))
        billable = max(0, min(net, capacity))
        remaining = billable
        earnings = 0.0
        for title, count in entries:
            allocated = min(count, remaining)
            remaining -= allocated
            earnings += allocated * prices.get(title, 0.0)
            if allocated > 0 and billable == capacity:
                popular.append((screen, title))
        rows.append((screen, earnings))
        total += earnings

    with open(os.path.join(folder, "revenue.csv"), "w") as f:
        f.write("screen,earnings\n")
        for screen, earnings in rows:
            f.write("%s,%.2f\n" % (screen, earnings))

    with open(os.path.join(folder, "oversold.txt"), "w") as f:
        for screen, net, capacity in oversold:
            f.write("screen %s sold %d of %d seats\n" % (screen, net, capacity))

    with open(os.path.join(folder, "popular.txt"), "w") as f:
        for screen, title in popular:
            f.write("%s (screen %s)\n" % (title, screen))

    with open(os.path.join(folder, "closing.log"), "w") as f:
        f.write("screens audited: %d\n" % len(rows))
        f.write("sold out screens: %d\n" % len({screen for screen, _ in popular}))
        f.write("oversold screens: %d\n" % len(oversold))
        f.write("total daily revenue: %.2f\n" % total)
    return total


if __name__ == "__main__":
    import sys

    folder = sys.argv[1] if len(sys.argv) > 1 else "."
    print("total revenue: %.2f" % audit(folder))

