import csv
import os


def load_animals(path):
    animals = []
    with open(path, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            animals.append({
                "name": row["name"].strip(),
                "species": row["species"].strip().lower(),
                "energy": int(row["energy"]),
            })
    return animals


def load_adopters(path):
    adopters = []
    with open(path, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            adopters.append({
                "name": row["name"].strip(),
                "species": row["species"].strip().lower(),
                "max_energy": int(row["max_energy"]),
            })
    return adopters


def load_restrictions(path):
    blocked = {}
    with open(path, encoding="utf-8") as f:
        for line in f:
            if ":" not in line:
                continue
            who, species = line.split(":", 1)
            names = {s.strip().lower() for s in species.split(",") if s.strip()}
            blocked.setdefault(who.strip(), set()).update(names)
    return blocked


def load_medical(path):
    treated = set()
    with open(path, encoding="utf-8") as f:
        for line in f:
            if line.strip():
                treated.add(line.strip())
    return treated


def match(folder):
    animals = load_animals(os.path.join(folder, "animals.csv"))
    adopters = load_adopters(os.path.join(folder, "adopters.csv"))
    blocked = load_restrictions(os.path.join(folder, "restrictions.txt"))
    medical = load_medical(os.path.join(folder, "medical.txt"))

    taken = set()
    pairs = []
    for adopter in adopters:
        forbidden = blocked.get(adopter["name"], set())
        for animal in animals:
            if animal["name"] in taken or animal["species"] != adopter["species"]:
                continue
            if animal["species"] in forbidden or animal["name"].lower() in forbidden:
                continue
            if animal["energy"] > adopter["max_energy"]:
                continue
            taken.add(animal["name"])
            pairs.append((adopter["name"], animal["name"]))
            break

    with open(os.path.join(folder, "adoptions.csv"), "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["adopter", "animal"])
        writer.writerows(pairs)
    with open(os.path.join(folder, "pending.txt"), "w", encoding="utf-8") as f:
        for animal in animals:
            if animal["name"] not in taken:
                f.write(animal["name"] + "\n")
    with open(os.path.join(folder, "care.csv"), "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["animal", "adopter"])
        for adopter_name, animal_name in pairs:
            if animal_name in medical:
                writer.writerow([animal_name, adopter_name])
    with open(os.path.join(folder, "daily.log"), "w", encoding="utf-8") as f:
        f.write("successful matches: {}\n".format(len(pairs)))
    return pairs


