    history = {}
    with open(path, "r", encoding="utf-8", newline="") as f:
        for row in csv.reader(f):
            if row:
                history[row[0].strip()] = float(row[1])
    return history


def read_sizes(path):
    sizes = {}
    with open(path, "r", encoding="utf-8", newline="") as f:
        for row in csv.reader(f):
            if row:
                sizes[row[0].strip()] = float(row[1])
    return sizes


def read_damage(path):
    damage = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if line:
                name, percent = line.split(":")
                damage[name.strip()] = float(percent.strip().rstrip("%"))
    return damage


def project(fields, history, sizes, damage):
    rows = []
    for name in sorted(fields):
        crop = fields[name]
        size = sizes[name]
        lost = damage.get(name, 0.0)
        expected = size * history[crop] * (1.0 - lost / 100.0)
        rows.append((name, crop, round(expected, 2), lost))
    return rows


def write_projections(path, rows):
    with open(path, "w", encoding="utf-8", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["field", "crop", "expected_yield"])
        for name, crop, expected, _lost in rows:
            writer.writerow([name, crop, expected])


def write_insurance(path, rows, threshold=10.0):
    with open(path, "w", encoding="utf-8") as f:
        for name, crop, expected, lost in rows:
            if lost >= threshold:
                f.write("%s (%s): %.1f%% lost to weather, %.2f expected\n"
                        % (name, crop, lost, expected))


def write_harvest(path, rows):
    totals = {}
    for _name, crop, expected, _lost in rows:
        totals[crop] = totals.get(crop, 0.0) + expected
    with open(path, "w", encoding="utf-8", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["crop", "total_expected_yield"])
        for crop in sorted(totals):
            writer.writerow([crop, round(totals[crop], 2)])
    return sum(totals.values())


def estimate(directory):
    fields = read_fields(os.path.join(directory, "fields.txt"))
    history = read_history(os.path.join(directory, "history.csv"))
    sizes = read_sizes(os.path.join(directory, "sizes.csv"))
    damage = read_damage(os.path.join(directory, "damage.txt"))
    rows = project(fields, history, sizes, damage)
    write_projections(os.path.join(directory, "projections.csv"), rows)
    write_insurance(os.path.join(directory, "insurance.txt"), rows)
    grand_total = write_harvest(os.path.join(directory, "harvest.csv"), rows)
    with open(os.path.join(directory, "season.log"), "w", encoding="utf-8") as f:
        f.write("fields projected: %d\n" % len(rows))
        f.write("grand total projected yield: %.2f\n" % grand_total)
    return grand_total


if __name__ == "__main__":
    import sys
    target = sys.argv[1] if len(sys.argv) > 1 else "."
    print("%.2f" % estimate(target))

