import csv
import os


def parse_clock(text):
    hours, minutes = text.strip().split(":")
    return int(hours) * 60 + int(minutes)


def read_stations(path):
    transit = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if line and not line.startswith("#"):
                name, minutes = line.rsplit(None, 1)
                transit[name] = int(minutes)
    return transit


def read_schedules(path):
    scheduled = {}
    with open(path, "r", encoding="utf-8", newline="") as f:
        for row in csv.reader(f):
            if len(row) == 3:
                train, station, clock = (field.strip() for field in row)
                scheduled[train] = (station, parse_clock(clock))
    return scheduled


def read_actuals(path):
    actual = {}
    with open(path, "r", encoding="utf-8", newline="") as f:
        for row in csv.reader(f):
            if len(row) == 2:
                train, clock = (field.strip() for field in row)
                actual[train] = parse_clock(clock)
    return actual


def read_incidents(path):
    failed = set()
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            train = line.strip()
            if train:
                failed.add(train)
    return failed


def audit(folder):
    transit = read_stations(os.path.join(folder, "stations.txt"))
    scheduled = read_schedules(os.path.join(folder, "schedules.csv"))
    actual = read_actuals(os.path.join(folder, "actuals.csv"))
    incidents = read_incidents(os.path.join(folder, "incidents.txt"))

    delays = {}
    for train, (station, planned) in sorted(scheduled.items()):
        if train in actual:
            delays[train] = (station, actual[train] - planned)

    with open(os.path.join(folder, "delays.csv"), "w", encoding="utf-8", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["train", "delay_minutes"])
        for train, (_station, delay) in delays.items():
            writer.writerow([train, delay])

    with open(os.path.join(folder, "ontime.txt"), "w", encoding="utf-8") as f:
        for train, (_station, delay) in delays.items():
            if delay == 0:
                f.write(train + "\n")

    with open(os.path.join(folder, "maintenance.csv"), "w", encoding="utf-8", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["train", "station", "delay_minutes", "normal_transit_minutes"])
        for train in sorted(incidents):
            if train in delays:
                station, delay = delays[train]
                writer.writerow([train, station, delay, transit.get(station, "unknown")])

    average = sum(delay for _station, delay in delays.values()) / len(delays) if delays else 0.0
    with open(os.path.join(folder, "daily.log"), "w", encoding="utf-8") as f:
        f.write("trains analyzed: %d\n" % len(delays))
        f.write("average delay: %.2f minutes\n" % average)
    return average


if __name__ == "__main__":
    import sys

    print("average delay: %.2f" % audit(sys.argv[1] if len(sys.argv) > 1 else "."))

