import os

PERIOD_FILES = {
    "morning": "morning_peak.log",
    "afternoon": "afternoon_flow.txt",
    "evening": "evening_transit.txt",
    "night": "night_quiet.txt",
}
CONGESTION_FACTOR = 1.25
QUIET_FACTOR = 0.6


def read_period(path):
    volumes = {}
    f = open(path, "r", encoding="utf-8")
    for line in f:
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        sensor, _, raw = line.partition(",")
        try:
            volumes[sensor.strip()] = int(raw.strip())
        except ValueError:
            continue
    f.close()
    return volumes


def historical_averages(readings):
    totals = {}
    for volumes in readings.values():
        for sensor, volume in volumes.items():
            totals.setdefault(sensor, []).append(volume)
    return {s: sum(v) / len(v) for s, v in totals.items()}


def find_anomalies(readings, averages):
    hotspots, quiet = [], []
    for period in ("morning", "afternoon", "evening", "night"):
        for sensor, volume in sorted(readings[period].items()):
            avg = averages[sensor]
            if volume > avg * CONGESTION_FACTOR:
                hotspots.append((period, sensor, volume, avg))
            elif volume < avg * QUIET_FACTOR:
                quiet.append((period, sensor, volume, avg))
    return hotspots, quiet


def analyze(zone):
    readings = {p: read_period(os.path.join(zone, name)) for p, name in PERIOD_FILES.items()}
    averages = historical_averages(readings)
    hotspots, quiet = find_anomalies(readings, averages)

    f = open(os.path.join(zone, "congestion_hotspots.txt"), "w", encoding="utf-8")
    f.write("period,sensor,volume,historical_average,excess_pct\n")
    for period, sensor, volume, avg in hotspots:
        f.write("%s,%s,%d,%.1f,%.1f\n" % (period, sensor, volume, avg, (volume / avg - 1) * 100))
    f.close()

    f = open(os.path.join(zone, "diversion_plan.txt"), "w", encoding="utf-8")
    for period, sensor, volume, avg in hotspots:
        reroute = int(volume - avg)
        f.write("During %s divert %d vehicles from %s to nearest arterial\n" % (period, reroute, sensor))
    if not hotspots:
        f.write("No diversions required; all sensors within historical tolerance\n")
    f.close()

    f = open(os.path.join(zone, "maintenance_schedule.txt"), "w", encoding="utf-8")
    for period, sensor, volume, avg in quiet:
        f.write("%s: resurfacing window on %s (volume %d vs average %.1f)\n" % (period, sensor, volume, avg))
    if not quiet:
        f.write("No low-traffic windows available this cycle\n")
    f.close()

    f = open(os.path.join(zone, "daily_digest.txt"), "w", encoding="utf-8")
    f.write("Zone: %s\n" % os.path.basename(os.path.abspath(zone)))
    for period in ("morning", "afternoon", "evening", "night"):
        volumes = readings[period]
        f.write("%-10s sensors=%d total=%d\n" % (period, len(volumes), sum(volumes.values())))
    f.write("Congestion hotspots: %d\n" % len(hotspots))
    f.write("Maintenance windows: %d\n" % len(quiet))
    f.close()

    return {"hotspots": hotspots, "maintenance_windows": quiet, "averages": averages}


def main():
    import sys
    zone = sys.argv[1] if len(sys.argv) > 1 else "."
    result = analyze(zone)
    print("hotspots=%d maintenance=%d" % (len(result["hotspots"]), len(result["maintenance_windows"])))


if __name__ == "__main__":
    main()

