import hashlib
import os


def expected_signature(txid, peer, address, amount):
    payload = f"{txid}:{peer}:{address}:{amount}".encode()
    return hashlib.sha256(payload).hexdigest()[:16]


def read_headers(path):
    headers = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = line.strip().split("|")
            if len(parts) == 3:
                headers.append((int(parts[0]), parts[1], parts[2]))
    return sorted(headers)


def read_peers(path):
    peers = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = line.strip().split("|")
            if len(parts) == 2:
                peers[parts[0]] = int(parts[1])
    return peers


def read_pending(path):
    queue = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = line.strip().split("|")
            if len(parts) == 5:
                queue.append(dict(txid=parts[0], peer=parts[1], address=parts[2],
                                  amount=parts[3], signature=parts[4]))
    return queue


def read_contracts(path):
    states = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = line.strip().split("|")
            if len(parts) == 3:
                states[parts[0]] = (parts[1], int(parts[2]))
    return states


def validate(nodepath):
    headers = read_headers(os.path.join(nodepath, "headers.txt"))
    peers = read_peers(os.path.join(nodepath, "peers.txt"))
    pending = read_pending(os.path.join(nodepath, "pending.txt"))
    contracts = read_contracts(os.path.join(nodepath, "contracts.txt"))

    banned = sorted(p for p, score in peers.items() if score < 50)
    chain, rejected = [], []
    prev_hash = "0" * 8
    for height, block_hash, parent in headers:
        if parent == prev_hash:
            chain.append((height, block_hash))
            prev_hash = block_hash

    with open(os.path.join(nodepath, "verified_chain.txt"), "w", encoding="utf-8") as f:
        for height, block_hash in chain:
            f.write(f"{height}|{block_hash}\n")

    accepted = 0
    for tx in pending:
        if tx["peer"] in banned:
            rejected.append((tx["txid"], "banned-peer"))
        elif tx["peer"] not in peers:
            rejected.append((tx["txid"], "unknown-peer"))
        elif tx["signature"] != expected_signature(tx["txid"], tx["peer"],
                                                   tx["address"], tx["amount"]):
            rejected.append((tx["txid"], "bad-signature"))
        elif contracts.get(tx["address"], ("missing", 0))[0] != "active":
            rejected.append((tx["txid"], "inactive-contract"))
        else:
            accepted += 1

    with open(os.path.join(nodepath, "rejected_tx.log"), "w", encoding="utf-8") as f:
        for txid, reason in rejected:
            f.write(f"{txid}\t{reason}\n")

    with open(os.path.join(nodepath, "banned_peers.txt"), "w", encoding="utf-8") as f:
        for peer in banned:
            f.write(f"{peer}|{peers[peer]}\n")

    with open(os.path.join(nodepath, "node_health.txt"), "w", encoding="utf-8") as f:
        f.write(f"headers_read {len(headers)}\n")
        f.write(f"chain_length {len(chain)}\n")
        f.write(f"peers_known {len(peers)}\n")
        f.write(f"peers_banned {len(banned)}\n")
        f.write(f"contracts_tracked {len(contracts)}\n")
        f.write(f"tx_accepted {accepted}\n")
        f.write(f"tx_rejected {len(rejected)}\n")

    return {"chain": len(chain), "accepted": accepted,
            "rejected": len(rejected), "banned": len(banned)}


if __name__ == "__main__":
    import sys

    summary = validate(sys.argv[1] if len(sys.argv) > 1 else ".")
    print("chain={chain} accepted={accepted} rejected={rejected} banned={banned}".format(**summary))

