import os
from datetime import date


def read_blueprint(path):
    zones = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if ":" in line:
                name, area = line.split(":", 1)
                zones[name.strip().lower()] = area.strip()
    return zones


def read_certifications(path):
    staff = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = [p.strip() for p in line.split(",")]
            if len(parts) == 3:
                staff.append((parts[0], parts[1], date.fromisoformat(parts[2])))
    return staff


def read_hygiene(path):
    entries = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = [p.strip() for p in line.split(",")]
            if len(parts) == 2:
                entries.append((parts[0], parts[1].lower()))
    return entries


def read_fire_registry(path):
    devices = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = [p.strip() for p in line.split(",")]
            if len(parts) == 3:
                devices.append((parts[0], parts[1], date.fromisoformat(parts[2])))
    return devices


def score(present, total):
    if total == 0:
        return 0
    return round(10.0 * present / total, 1)


def audit(store):
    today = date.today()
    required_zones = ("entrance", "stockroom", "checkout", "restroom", "exit")
    zones = read_blueprint(os.path.join(store, "blueprint.txt"))
    staff = read_certifications(os.path.join(store, "certifications.txt"))
    hygiene = read_hygiene(os.path.join(store, "hygiene_log.txt"))
    devices = read_fire_registry(os.path.join(store, "fire_registry.txt"))

    missing_zones = [z for z in required_zones if z not in zones]
    expired_staff = [(n, c) for n, c, d in staff if d < today]
    failed_areas = [a for a, verdict in hygiene if verdict != "pass"]
    bad_devices = [(i, k) for i, k, d in devices if d < today]

    grades = {
        "layout": score(len(required_zones) - len(missing_zones), len(required_zones)),
        "certification": score(len(staff) - len(expired_staff), len(staff)),
        "hygiene": score(len(hygiene) - len(failed_areas), len(hygiene)),
        "fire safety": score(len(devices) - len(bad_devices), len(devices)),
    }

    with open(os.path.join(store, "passing_scores.txt"), "w", encoding="utf-8") as f:
        for name, value in grades.items():
            if value >= 8.0:
                f.write("%s passed with %.1f/10\n" % (name, value))

    with open(os.path.join(store, "warning_notices.txt"), "w", encoding="utf-8") as f:
        for zone in missing_zones:
            f.write("Missing zone in blueprint: %s\n" % zone)
        for area in failed_areas:
            f.write("Hygiene failure recorded: %s\n" % area)
        for ident, kind in bad_devices:
            f.write("Fire equipment overdue: %s (%s)\n" % (ident, kind))

    with open(os.path.join(store, "training_syllabus.txt"), "w", encoding="utf-8") as f:
        for name, cert in expired_staff:
            f.write("Renew %s certification for %s\n" % (cert, name))

    total = round(sum(grades.values()) / len(grades), 2)
    with open(os.path.join(store, "audit_scorecard.txt"), "w", encoding="utf-8") as f:
        f.write("Audit for %s on %s\n" % (store, today.isoformat()))
        for name, value in grades.items():
            f.write("  %-14s %.1f/10\n" % (name, value))
        f.write("Overall: %.2f/10 (%s)\n" % (total, "COMPLIANT" if total >= 8 else "ACTION REQUIRED"))
    return total


if __name__ == "__main__":
    import sys

    print(audit(sys.argv[1] if len(sys.argv) > 1 else "."))

