import os


def read_scenes(path):
    scenes = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if line.strip() and not line.startswith("#"):
                sid, loc, start, cast, extras, desc = line.strip().split("|")
                scenes.append({"id": sid, "location": loc, "start": start,
                               "cast": [a.strip() for a in cast.split(",") if a.strip()],
                               "extras": int(extras), "desc": desc})
    return scenes


def read_actors(path):
    actors = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if line.strip():
                name, status, call = line.strip().split("|")
                actors[name] = {"status": status.lower(), "call": call}
    return actors


def read_props(path):
    props = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if line.strip():
                sid, items = line.strip().split("|")
                props[sid] = [p.strip() for p in items.split(",") if p.strip()]
    return props


def read_permits(path):
    permits = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if line.strip():
                loc, cleared, window = line.strip().split("|")
                permits[loc] = {"cleared": cleared.strip().lower() == "yes", "window": window}
    return permits


def organize(shoot):
    scenes = read_scenes(os.path.join(shoot, "scenes.txt"))
    actors = read_actors(os.path.join(shoot, "actors.txt"))
    props = read_props(os.path.join(shoot, "props.txt"))
    permits = read_permits(os.path.join(shoot, "permits.txt"))

    shootable, blocked = [], []
    for scene in scenes:
        permit = permits.get(scene["location"], {"cleared": False, "window": "no permit"})
        missing = [a for a in scene["cast"] if actors.get(a, {}).get("status") != "available"]
        if permit["cleared"] and not missing:
            shootable.append((scene, permit))
        else:
            reason = "location not cleared" if not permit["cleared"] else "cast out: " + ", ".join(missing)
            blocked.append((scene, reason))

    with open(os.path.join(shoot, "call_sheet.txt"), "w", encoding="utf-8") as f:
        f.write("MAIN CAST CALL SHEET\n")
        for scene, _permit in shootable:
            for actor in scene["cast"]:
                f.write("%s - call %s - scene %s at %s\n" % (actor, actors[actor]["call"], scene["id"], scene["location"]))

    with open(os.path.join(shoot, "extras_plan.txt"), "w", encoding="utf-8") as f:
        f.write("EXTRAS COORDINATION PLAN\n")
        total = 0
        for scene, _permit in shootable:
            total += scene["extras"]
            f.write("Scene %s: %d extras at %s (%s)\n" % (scene["id"], scene["extras"], scene["location"], scene["start"]))
        f.write("Total extras needed: %d\n" % total)

    with open(os.path.join(shoot, "prop_checklist.txt"), "w", encoding="utf-8") as f:
        f.write("PROP DEPARTMENT CHECKLIST\n")
        for scene, _permit in shootable:
            for item in props.get(scene["id"], ["none listed"]):
                f.write("[ ] %s -> scene %s\n" % (item, scene["id"]))

    with open(os.path.join(shoot, "shooting_schedule.txt"), "w", encoding="utf-8") as f:
        f.write("DAILY SHOOTING SCHEDULE\n")
        for scene, permit in sorted(shootable, key=lambda p: p[0]["start"]):
            f.write("%s | Scene %s | %s (%s) | %s\n" % (scene["start"], scene["id"],
                                                        scene["location"], permit["window"], scene["desc"]))
        for scene, reason in blocked:
            f.write("POSTPONED | Scene %s | %s\n" % (scene["id"], reason))

    return {"scheduled": [s["id"] for s, _ in shootable],
            "postponed": [s["id"] for s, _ in blocked]}


if __name__ == "__main__":
    import sys
    report = organize(sys.argv[1] if len(sys.argv) > 1 else ".")
    print("Scheduled:", ", ".join(report["scheduled"]) or "none")
    print("Postponed:", ", ".join(report["postponed"]) or "none")

