import os
from collections import defaultdict


def read_assets(path):
    assets = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = [p.strip() for p in line.split(",")]
            if len(parts) == 3 and parts[1].replace(".", "", 1).isdigit():
                assets.append((parts[0], float(parts[1]), parts[2]))
    return assets


def read_roster(path):
    staff = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = [p.strip() for p in line.split(",")]
            if len(parts) == 4 and parts[2].replace(".", "", 1).isdigit():
                staff.append({"name": parts[0], "role": parts[1],
                              "salary": float(parts[2]), "company": parts[3]})
    return staff


def read_licenses(path):
    licenses = defaultdict(list)
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = [p.strip() for p in line.split(",")]
            if len(parts) == 4 and parts[1].isdigit():
                licenses[parts[0]].append((parts[3], int(parts[1]), float(parts[2])))
    return licenses


def read_contracts(path):
    contracts = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = [p.strip() for p in line.split(",")]
            if len(parts) == 3 and parts[1].replace(".", "", 1).isdigit():
                contracts.append((parts[0], float(parts[1]), parts[2].lower()))
    return contracts


def split_staff(staff):
    by_role = defaultdict(list)
    for person in staff:
        by_role[person["role"]].append(person)
    retained, released = [], []
    for role, people in sorted(by_role.items()):
        people.sort(key=lambda p: (p["salary"], p["name"]))
        retained.append(people[0])
        released.extend(people[1:])
    return retained, released


def reconcile(merger):
    assets = read_assets(os.path.join(merger, "assets.csv"))
    staff = read_roster(os.path.join(merger, "roster.csv"))
    licenses = read_licenses(os.path.join(merger, "licenses.csv"))
    contracts = read_contracts(os.path.join(merger, "contracts.csv"))
    retained, released = split_staff(staff)

    with open(os.path.join(merger, "retention_plan.txt"), "w", encoding="utf-8") as f:
        for person in retained:
            f.write("{name},{role},{company},{salary:.2f}\n".format(**person))

    severance = 0.0
    with open(os.path.join(merger, "severance_estimate.txt"), "w", encoding="utf-8") as f:
        for person in released:
            package = round(person["salary"] * 0.25, 2)
            severance += package
            f.write("%s,%s,%.2f\n" % (person["name"], person["role"], package))
        f.write("TOTAL,%.2f\n" % severance)

    savings = 0.0
    with open(os.path.join(merger, "cancellations.txt"), "w", encoding="utf-8") as f:
        for product, entries in sorted(licenses.items()):
            entries.sort(key=lambda e: e[2])
            for company, seats, cost in entries[1:]:
                savings += seats * cost
                f.write("%s,%s,%d seats,%.2f\n" % (product, company, seats, seats * cost))
        for vendor, cost, status in contracts:
            if status == "disputed":
                savings += cost
                f.write("%s,contract,%.2f\n" % (vendor, cost))
        f.write("SAVINGS,%.2f\n" % savings)

    with open(os.path.join(merger, "asset_portfolio.txt"), "w", encoding="utf-8") as f:
        kept = {}
        for name, value, owner in assets:
            if name not in kept or value > kept[name][0]:
                kept[name] = (value, owner)
        for name in sorted(kept):
            f.write("%s,%.2f,%s\n" % (name, kept[name][0], kept[name][1]))
        f.write("NET,%.2f\n" % (sum(v for v, _ in kept.values()) + savings - severance))


if __name__ == "__main__":
    reconcile(os.path.join(os.path.dirname(os.path.abspath(__file__)), "merger"))

