                gas, ppm = line.split()
                readings[gas.lower()] = float(ppm)
    return readings


def read_structural_scan(path):
    supports = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if line.strip():
                name, strength = line.split()
                supports.append((name, float(strength)))
    return supports


def read_worker_registry(path):
    crew = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if line.strip():
                zone, count = line.split()
                crew[zone] = int(count)
    return crew


def read_fuel_summary(path):
    tanks = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if line.strip():
                machine, percent = line.split()
                tanks[machine] = float(percent)
    return tanks


def collect_alerts(air, supports):
    alerts = []
    if air.get("co", 0.0) > 35.0:
        alerts.append("ALERT: carbon monoxide at %.1f ppm exceeds 35 ppm" % air["co"])
    for name, strength in supports:
        if strength < 0.70:
            alerts.append("ALERT: ceiling support %s weakened to %.2f" % (name, strength))
    return alerts


def write_evacuation_plan(path, crew, alerts):
    total = sum(crew.values())
    with open(path, "w", encoding="utf-8") as f:
        f.write("EVACUATION READINESS PLAN\n")
        f.write("workers underground: %d\n" % total)
        for zone in sorted(crew, key=lambda z: -crew[z]):
            f.write("%s: %d workers -> hoist cage %s\n" % (zone, crew[zone], zone[:1].upper()))
        f.write("status: %s\n" % ("IMMEDIATE EVACUATION" if alerts else "standby"))


def write_ventilation_order(path, air):
    with open(path, "w", encoding="utf-8") as f:
        f.write("VENTILATION ADJUSTMENT ORDER\n")
        for gas in sorted(air):
            f.write("%s measured %.1f ppm\n" % (gas, air[gas]))
        fan_speed = min(100, 40 + int(air.get("co", 0.0) * 1.5) + int(air.get("methane", 0.0)))
        f.write("main fan speed: %d%%\n" % fan_speed)


def write_maintenance_list(path, tanks):
    with open(path, "w", encoding="utf-8") as f:
        f.write("EQUIPMENT MAINTENANCE LIST\n")
        for machine in sorted(tanks):
            level = tanks[machine]
            action = "refuel now" if level < 25.0 else "inspect at shift end"
            f.write("%s (%.0f%% fuel): %s\n" % (machine, level, action))


def write_safety_certificate(path, shaft, alerts, crew):
    with open(path, "w", encoding="utf-8") as f:
        f.write("SHIFT SAFETY CERTIFICATE - shaft %s\n" % shaft)
        f.write("crew accounted for: %d\n" % sum(crew.values()))
        if alerts:
            f.write("certificate WITHHELD\n")
            for alert in alerts:
                f.write("%s\n" % alert)
        else:
            f.write("certificate GRANTED - shaft cleared for production\n")
    return not alerts


def evaluate(shaft):
    air = read_air_quality(os.path.join(shaft, "air_quality.log"))
    supports = read_structural_scan(os.path.join(shaft, "structural_scan.txt"))
    crew = read_worker_registry(os.path.join(shaft, "worker_registry.txt"))
    tanks = read_fuel_summary(os.path.join(shaft, "fuel_summary.txt"))
    alerts = collect_alerts(air, supports)
    for alert in alerts:
        print(alert)
    write_evacuation_plan(os.path.join(shaft, "evacuation_plan.txt"), crew, alerts)
    write_ventilation_order(os.path.join(shaft, "ventilation_order.txt"), air)
    write_maintenance_list(os.path.join(shaft, "maintenance_list.txt"), tanks)
    certified = write_safety_certificate(
        os.path.join(shaft, "safety_certificate.txt"), os.path.basename(shaft.rstrip(os.sep)), alerts, crew
    )
    return certified


if __name__ == "__main__":
    for directory in sys.argv[1:]:
        cleared = evaluate(directory)
        print("%s: %s" % (directory, "cleared" if cleared else "held"))

