import os
import csv

URGENT_BULB_HOURS = 250
URGENT_FUEL_DAYS = 5.0
URGENT_CRACK_SCORE = 6.0


def read_bulbs(path):
    bulbs = {}
    with open(path, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            bulbs[row["lighthouse"]] = float(row["bulb_hours_left"])
    return bulbs


def read_fuel(path):
    fuel = {}
    with open(path, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            litres = float(row["litres_in_tank"])
