import math
import os
import statistics
import sys


def read_matrix(path):
    rows = []
    with open(path) as f:
        for line in f:
            values = line.split()
            if values:
                rows.append([float(v) for v in values])
    return rows


def read_mask(path):
    rows = []
    with open(path) as f:
        for line in f:
            values = line.split()
            if values:
                rows.append([float(v) != 0.0 for v in values])
    return rows


def write_image(path, image):
    with open(path, "w") as f:
        for row in image:
            f.write(" ".join("%.4f" % value for value in row) + "\n")


def write_headers(path, height, width):
    headers = [("NAXIS", 2), ("NAXIS1", width), ("NAXIS2", height),
               ("CRPIX1", width / 2.0), ("CRPIX2", height / 2.0),
               ("CDELT1", -0.000278), ("CDELT2", 0.000278),
               ("CTYPE1", "RA---TAN"), ("CTYPE2", "DEC--TAN")]
    with open(path, "w") as f:
        for key, value in headers:
            f.write("%-8s= %s\n" % (key, value))


def detect_sources(image, sigma=3.0):
    flat_values = [value for row in image for value in row]
    level = statistics.mean(flat_values) + sigma * statistics.pstdev(flat_values)
    sources = []
    for y in range(1, len(image) - 1):
        for x in range(1, len(image[y]) - 1):
            value = image[y][x]
            if value < level:
                continue
            neighbours = [image[y + dy][x + dx]
                          for dy in (-1, 0, 1) for dx in (-1, 0, 1)
                          if dy or dx]
            if value >= max(neighbours):
                sources.append((x, y, value))
    return sources


def write_catalog(path, sources):
    with open(path, "w") as f:
        f.write("id x y flux mag\n")
        for index, (x, y, flux) in enumerate(sources, start=1):
            mag = -2.5 * math.log10(flux) if flux > 0 else 99.0
            f.write("%d %d %d %.4f %.3f\n" % (index, x, y, flux, mag))


def write_log(path, entries):
    with open(path, "w") as f:
        for entry in entries:
            f.write(entry + "\n")


def calibrate(directory):
    raw = read_matrix(os.path.join(directory, "raw.txt"))
    bias = read_matrix(os.path.join(directory, "dark.txt"))
    flat = read_matrix(os.path.join(directory, "flat.txt"))
    mask = read_mask(os.path.join(directory, "mask.txt"))
    shapes = {tuple(len(row) for row in frame) for frame in (raw, bias, flat, mask)}
    if len(shapes) != 1:
        raise ValueError("input frames have mismatched dimensions")
    height = len(raw)
    width = len(raw[0]) if height else 0
    image = []
    for y in range(height):
        row = []
        for x in range(width):
            gain = flat[y][x]
            if gain == 0.0:
                raise ValueError("flat field has zero response at %d,%d" % (x, y))
            row.append((raw[y][x] - bias[y][x]) / gain)
        image.append(row)
    interpolated = 0
    for y in range(height):
        for x in range(width):
            if not mask[y][x]:
                continue
            good = [image[y + dy][x + dx]
                    for dy in (-1, 0, 1) for dx in (-1, 0, 1)
                    if (dy or dx) and 0 <= y + dy < height and 0 <= x + dx < width
                    and not mask[y + dy][x + dx]]
            if good:
                image[y][x] = sum(good) / len(good)
                interpolated += 1
    corrected = sum(1 for y in range(height) for x in range(width)
                    if image[y][x] != raw[y][x])
    sources = detect_sources(image)
    write_image(os.path.join(directory, "calibrated.txt"), image)
    write_headers(os.path.join(directory, "astrometry.hdr"), height, width)
    write_catalog(os.path.join(directory, "catalog.txt"), sources)
    write_log(os.path.join(directory, "calibration.log"), [
        "frame size: %dx%d" % (width, height),
        "bias subtracted and flat fielded",
        "cosmic ray pixels interpolated: %d" % interpolated,
        "pixels corrected: %d" % corrected,
        "sources cataloged: %d" % len(sources)])
    return corrected, len(sources)


def main():
    directory = sys.argv[1] if len(sys.argv) > 1 else "."
    corrected, sources = calibrate(directory)
    print("corrected pixels: %d, sources: %d" % (corrected, sources))


if __name__ == "__main__":
    main()

