import os
import sys


def load_telemetry(path):
    fixes = []
    with open(path) as f:
        for line in f:
            parts = line.strip().split(",")
            if len(parts) == 4:
                t, lat, lon, depth = parts
                fixes.append((float(t), float(lat), float(lon), float(depth)))
    return sorted(fixes)


def load_soundings(path):
    soundings = []
    with open(path) as f:
        for line in f:
            parts = line.split()
            if len(parts) == 2:
                soundings.append((float(parts[0]), float(parts[1])))
    return sorted(soundings)


def load_chemistry(path):
    samples = []
    with open(path) as f:
        for line in f:
            if line.startswith("#"):
                continue
            parts = line.strip().split(",")
            if len(parts) == 4:
                samples.append(tuple(float(p) for p in parts))
    return samples


def load_highlights(path):
    marks = []
    with open(path) as f:
        for line in f:
            t, _, label = line.strip().partition(",")
            if label:
                marks.append((float(t), label.strip()))
    return marks


def fix_at(fixes, t):
    return min(fixes, key=lambda fx: abs(fx[0] - t))


def classify(gradient):
    if gradient > 40.0:
        return "escarpment wall"
    if gradient > 10.0:
        return "ridge flank"
    if gradient < -10.0:
        return "sediment basin"
    return "abyssal plain"


def write_geology(path, soundings, fixes):
    with open(path, "w") as f:
        f.write("time,lat,lon,depth,formation\n")
        for (t0, d0), (t1, d1) in zip(soundings, soundings[1:]):
            gradient = (d1 - d0) / max(t1 - t0, 1e-6)
            _, lat, lon, _ = fix_at(fixes, t1)
            f.write("%.1f,%.5f,%.5f,%.1f,%s\n" % (t1, lat, lon, d1, classify(gradient)))


def write_specimens(path, marks, fixes):
    with open(path, "w") as f:
        f.write("specimen,time,lat,lon,depth\n")
        for index, (t, label) in enumerate(sorted(marks), 1):
            _, lat, lon, depth = fix_at(fixes, t)
            f.write("SP-%03d,%.1f,%.5f,%.5f,%.1f,%s\n" % (index, t, lat, lon, depth, label))


def write_wear(path, fixes, anomalies):
    duration = fixes[-1][0] - fixes[0][0]
    deepest = max(fx[3] for fx in fixes)
    cycles = sum(1 for a, b in zip(fixes, fixes[1:]) if (b[3] - a[3]) * (a[3] - b[3]) < 0)
    with open(path, "w") as f:
        f.write("Hull pressure cycles: %d\n" % cycles)
        f.write("Peak hull load: %.1f bar\n" % (deepest / 10.0))
        f.write("Thruster runtime: %.1f min\n" % (duration / 60.0))
        f.write("Corrosive exposure events: %d\n" % len(anomalies))
        f.write("Sensor recalibration due: %s\n" % ("yes" if anomalies else "no"))


def write_summary(path, fixes, soundings, anomalies, marks, max_depth):
    with open(path, "w") as f:
        f.write("SUBMARINE DIVE DEBRIEF\n")
        f.write("Telemetry fixes: %d\n" % len(fixes))
        f.write("Sonar soundings: %d\n" % len(soundings))
        f.write("Maximum depth: %.1f m\n" % max_depth)
        f.write("Specimens catalogued: %d\n" % len(marks))
        for t, lat, lon, ph in anomalies:
            f.write("Anomaly at %.1f s (%.5f, %.5f): pH %.2f\n" % (t, lat, lon, ph))


def debrief(directory):
    fixes = load_telemetry(os.path.join(directory, "telemetry.csv"))
    soundings = load_soundings(os.path.join(directory, "sonar.txt"))
    samples = load_chemistry(os.path.join(directory, "chemistry.csv"))
    marks = load_highlights(os.path.join(directory, "highlights.txt"))
    anomalies = []
    for t, temperature, salinity, ph in samples:
        if ph < 7.6 or temperature > 6.0 or salinity > 36.0:
            _, lat, lon, _ = fix_at(fixes, t)
            anomalies.append((t, lat, lon, ph))
    max_depth = max([fx[3] for fx in fixes] + [d for _, d in soundings])
    write_geology(os.path.join(directory, "geology_map.csv"), soundings, fixes)
    write_specimens(os.path.join(directory, "specimen_catalog.csv"), marks, fixes)
    write_wear(os.path.join(directory, "equipment_wear.txt"), fixes, anomalies)
    write_summary(os.path.join(directory, "dive_summary.txt"), fixes, soundings,
                  anomalies, marks, max_depth)
    return float(max_depth)


if __name__ == "__main__":
    folder = sys.argv[1] if len(sys.argv) > 1 else "."
    print("Maximum depth reached: %.1f m" % debrief(folder))

