import os
import sys
from collections import Counter


def read_knights(path):
    knights = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            record = line.strip()
            if record and not record.startswith("#"):
                name, skill = record.split(",")
                knights[name.strip()] = int(skill)
    return knights


def read_bracket(path):
    pairs = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            match = line.strip()
            if match:
                pairs.append(tuple(part.strip() for part in match.split(" vs ")))
    return pairs


def read_inventory(path):
    stock = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            entry = line.strip()
            if entry:
                item, count = entry.split(":")
                stock[item.strip().lower()] = int(count)
    return stock


def read_pledges(path):
    gold = 0
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            entry = line.strip()
            if entry.lower().startswith("gold_per_win"):
                gold = int(entry.split(":")[1])
    return gold


def equip_knights(pairs, stock, deficit_path):
    sets = min(stock.get("lances", 0), stock.get("armor", 0))
    order = [name for pair in pairs for name in pair]
    equipped = set(order[:sets])
    with open(deficit_path, "w", encoding="utf-8") as f:
        for name in order[sets:]:
            f.write("%s: missing 1 lance and 1 armor set\n" % name)
    return equipped


def joust(left, right, skills, equipped):
    if left not in equipped:
        return right
    if right not in equipped:
        return left
    if skills.get(left, 0) != skills.get(right, 0):
        return left if skills.get(left, 0) > skills.get(right, 0) else right
    return min(left, right)


def simulate(pairs, skills, equipped):
    wins = Counter()
    rounds = []
    current = pairs
    while current:
        results = []
        for pair in current:
            if len(pair) == 1:
                results.append((pair, pair[0]))
                continue
            champion = joust(pair[0], pair[1], skills, equipped)
            wins[champion] += 1
            results.append((pair, champion))
        rounds.append(results)
        survivors = [entry[1] for entry in results]
        if len(survivors) < 2:
            break
        current = [tuple(survivors[i:i + 2]) for i in range(0, len(survivors), 2)]
    return rounds, wins


def write_bracket(path, rounds):
    with open(path, "w", encoding="utf-8") as f:
        for number, results in enumerate(rounds, start=1):
            f.write("Round %d\n" % number)
            for pair, champion in results:
                f.write("  %s -> %s\n" % (" vs ".join(pair), champion))


def write_leaderboard(path, wins, skills):
    ranking = sorted(skills, key=lambda n: (-wins[n], -skills[n], n))
    with open(path, "w", encoding="utf-8") as f:
        for place, name in enumerate(ranking, start=1):
            f.write("%d. %s - %d wins (skill %d)\n" % (place, name, wins[name], skills[name]))


def write_ledger(path, wins, skills, gold_per_win):
    names = set(skills) | set(wins)
    total = 0
    with open(path, "w", encoding="utf-8") as f:
        f.write("Prize money at %d gold per victory\n" % gold_per_win)
        for name in sorted(names, key=lambda n: (-wins[n], n)):
            owed = wins[name] * gold_per_win
            total += owed
            f.write("%s: %d gold\n" % (name, owed))
        f.write("Total owed: %d gold\n" % total)


def tournament(directory):
    skills = read_knights(os.path.join(directory, "knights.txt"))
    pairs = read_bracket(os.path.join(directory, "bracket.txt"))
    stock = read_inventory(os.path.join(directory, "inventory.txt"))
    gold_per_win = read_pledges(os.path.join(directory, "sponsors.txt"))
    equipped = equip_knights(pairs, stock, os.path.join(directory, "equipment_deficit.txt"))
    rounds, wins = simulate(pairs, skills, equipped)
    write_bracket(os.path.join(directory, "bracket_updated.txt"), rounds)
    write_leaderboard(os.path.join(directory, "leaderboard.txt"), wins, skills)
    write_ledger(os.path.join(directory, "ledger.txt"), wins, skills, gold_per_win)
    return rounds[-1][0][1] if rounds else None


if __name__ == "__main__":
    champion = tournament(sys.argv[1] if len(sys.argv) > 1 else ".")
    print("Tournament champion: %s" % champion)

