    winds = {}
    with open(path, "r") as f:
        for line in f:
            parts = line.split()
            if len(parts) == 2:
                winds[parts[0].lower()] = float(parts[1])
    return winds

def read_monsters(path):
    monsters = []
    with open(path, "r") as f:
        for line in f:
            parts = line.replace(",", " ").split()
            if len(parts) >= 2:
                monsters.append((float(parts[0]), float(parts[1])))
    return monsters

def read_target(path):
    with open(path, "r") as f:
        for line in f:
            parts = line.replace(",", " ").split()
            if parts and parts[0].lower() == "dig":
                return float(parts[1]), float(parts[2]), " ".join(parts[3:])
    raise ValueError("terrain map has no dig marker")

def plan_route(start, target, monsters, winds):
    route = [start]
    bypassed = []
    lat, lon = start
    steps = 5
    dlat = (target[0] - lat) / steps
    dlon = (target[1] - lon) / steps
    for _ in range(steps):
        lat, lon = lat + dlat, lon + dlon
        for mlat, mlon in monsters:
            if abs(mlat - lat) < 0.5 and abs(mlon - lon) < 0.5:
                shift = 1.0 / winds.get("north", 1.0)
                lat += shift
                bypassed.append((mlat, mlon))
        route.append((lat, lon))
    return route, bypassed

def hunt(directory):
    start = read_start(os.path.join(directory, "captain_log.txt"))
    winds = read_winds(os.path.join(directory, "wind_currents.txt"))
    monsters = read_monsters(os.path.join(directory, "monster_sightings.txt"))
    target_lat, target_lon, loot = read_target(os.path.join(directory, "terrain_map.txt"))
    route, bypassed = plan_route(start, (target_lat, target_lon), monsters, winds)

    with open(os.path.join(directory, "safe_route.txt"), "w") as f:
        for lat, lon in route:
            f.write("{:.2f} {:.2f}\n".format(lat, lon))

    with open(os.path.join(directory, "hazard_warning.txt"), "w") as f:
        for mlat, mlon in bypassed:
            f.write("bypassed monster at {:.2f} {:.2f}\n".format(mlat, mlon))

    with open(os.path.join(directory, "treasure_inventory.txt"), "w") as f:
        f.write("dig site: {:.2f} {:.2f}\n".format(target_lat, target_lon))
        f.write("expected loot: {}\n".format(loot or "unknown hoard"))

    distance = 0.0
    for (alat, alon), (blat, blon) in zip(route, route[1:]):
        distance += ((blat - alat) ** 2 + (blon - alon) ** 2) ** 0.5

    with open(os.path.join(directory, "journey_summary.txt"), "w") as f:
        f.write("{:g} leagues traveled\n".format(round(distance, 2)))
    return round(distance, 2)

