import os


def read_answer_key(path):
    key = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if ":" in line:
                spell, incantation = line.split(":", 1)
                key[spell.strip()] = incantation.strip().lower()
    return key


def read_roster(path):
    roster = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if "," in line:
                name, house = line.split(",", 1)
                roster[name.strip()] = house.strip()
    return roster


def read_rubric(path):
    rubric = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if "=" in line:
                spell, points = line.split("=", 1)
                rubric[spell.strip()] = int(points.strip())
    return rubric


def read_disciplinary(path):
    penalties = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if "-" in line:
                name, amount = line.rsplit("-", 1)
                penalties[name.strip()] = penalties.get(name.strip(), 0) + int(amount.strip())
    return penalties


def read_submission(path, key, rubric):
    score = 0
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if ":" in line:
                spell, attempt = line.split(":", 1)
                spell = spell.strip()
                if key.get(spell) == attempt.strip().lower():
                    score += rubric.get(spell, 0)
    return score


def grade(directory):
    key = read_answer_key(os.path.join(directory, "answer_key.txt"))
    roster = read_roster(os.path.join(directory, "roster.txt"))
    rubric = read_rubric(os.path.join(directory, "rubric.txt"))
    penalties = read_disciplinary(os.path.join(directory, "disciplinary_records.txt"))

    scores = {}
    for name in roster:
        submission = os.path.join(directory, name.replace(" ", "_") + "_exam.txt")
        raw = read_submission(submission, key, rubric)
        scores[name] = raw - penalties.get(name, 0)

    with open(os.path.join(directory, "passing_grades.txt"), "w", encoding="utf-8") as f:
        for name, score in sorted(scores.items()):
            if score >= 70:
                f.write("%s (%s): %d\n" % (name, roster[name], score))

    with open(os.path.join(directory, "remedial_studies.txt"), "w", encoding="utf-8") as f:
        for name, score in sorted(scores.items()):
            if score < 70:
                f.write("%s (%s): %d needs remedial work\n" % (name, roster[name], score))

    standings = {}
    for name, score in scores.items():
        standings[roster[name]] = standings.get(roster[name], 0) + score

    with open(os.path.join(directory, "house_cup_standings.txt"), "w", encoding="utf-8") as f:
        for house, total in sorted(standings.items(), key=lambda item: -item[1]):
            f.write("%s: %d points\n" % (house, total))

    top = max(scores.items(), key=lambda item: item[1])
    with open(os.path.join(directory, "honors_announcement.txt"), "w", encoding="utf-8") as f:
        f.write("Top Scholar: %s of %s with %d points\n" % (top[0], roster[top[0]], top[1]))

    return scores


if __name__ == "__main__":
    import sys

    results = grade(sys.argv[1] if len(sys.argv) > 1 else ".")
    for student, total in sorted(results.items()):
        print(student, total)

