import os


def load_suspects(path):
    suspects = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if ":" in line:
                name, motive = line.split(":", 1)
                suspects[name.strip()] = motive.strip()
    return suspects


def load_alibis(path):
    alibis = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if ":" in line:
                name, statement = line.split(":", 1)
                alibis[name.strip()] = statement.strip()
    return alibis


def load_evidence(path):
    evidence = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if "->" in line:
                print_id, name = line.split("->", 1)
                evidence.setdefault(name.strip(), []).append(print_id.strip())
    return evidence


def load_timeline(path):
    events = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if "|" in line:
                hour, description = line.split("|", 1)
                events[int(hour.strip())] = description.strip()
    return events


def write_cleared(path, cleared):
    with open(path, "w", encoding="utf-8") as f:
        for name, statement in sorted(cleared.items()):
            f.write("%s cleared by alibi: %s\n" % (name, statement))


def write_prime(path, prime):
    with open(path, "w", encoding="utf-8") as f:
        for name, prints in sorted(prime.items()):
            f.write("%s: no alibi, prints %s\n" % (name, ", ".join(prints)))


def write_gaps(path, gaps):
    with open(path, "w", encoding="utf-8") as f:
        if gaps:
            for hour in gaps:
                f.write("Hour %02d:00 unaccounted for\n" % hour)
        else:
            f.write("Timeline complete, no gaps\n")


def investigate(folder):
    suspects = load_suspects(os.path.join(folder, "suspects.txt"))
    alibis = load_alibis(os.path.join(folder, "alibis.txt"))
    evidence = load_evidence(os.path.join(folder, "evidence.txt"))

    cleared = {n: alibis[n] for n in suspects if n in alibis}
    prime = {n: evidence[n] for n in suspects if n not in alibis and n in evidence}

    write_cleared(os.path.join(folder, "cleared_suspects.txt"), cleared)
    write_prime(os.path.join(folder, "prime_suspects.txt"), prime)

    events = load_timeline(os.path.join(folder, "timeline.txt"))
    span = range(min(events), max(events) + 1) if events else range(0)
    gaps = [h for h in span if h not in events]
    write_gaps(os.path.join(folder, "timeline_gaps.txt"), gaps)

    culprit = max(prime, key=lambda n: len(prime[n])) if prime else None
    with open(os.path.join(folder, "deduction.txt"), "w", encoding="utf-8") as f:
