    return reserves


def read_clan(path):
    members = []
    with open(path, "r") as f:
        for line in f:
            parts = [p.strip() for p in line.split(",")]
            if len(parts) == 3:
                members.append({"name": parts[0], "rank": parts[1], "need": float(parts[2])})
    members.sort(key=lambda m: -m["need"])
    return members


def read_forecast(path):
    days = []
    with open(path, "r") as f:
        for line in f:
            parts = [p.strip() for p in line.split(",")]
            if len(parts) == 3:
                days.append({"day": parts[0], "cloud": float(parts[1]), "zone": parts[2]})
    return days


def read_sightings(path):
    sightings = {}
    with open(path, "r") as f:
        for line in f:
            parts = [p.strip() for p in line.split(",")]
            if len(parts) == 2:
                sightings[parts[0]] = int(parts[1])
    return sightings


def write_safe_zones(path, forecast):
    with open(path, "w") as f:
        for day in forecast:
            status = "SAFE" if day["cloud"] >= 70 else "COFFIN"
            f.write("%s %s cloud=%.0f%% %s\n" % (day["day"], day["zone"], day["cloud"], status))


def write_warning(path, reserves, weekly_need):
    total = sum(reserves.values())
    deficit = weekly_need - total
    with open(path, "w") as f:
        f.write("Reserves: %.1f pints\nWeekly need: %.1f pints\n" % (total, weekly_need))
        f.write("DEFICIT: %.1f pints - emergency hunt required\n" % deficit)
    return deficit


def write_relocation(path, forecast, sightings):
    with open(path, "w") as f:
        for day in forecast:
            hunters = sightings.get(day["zone"], 0)
            target = min(forecast, key=lambda d: sightings.get(d["zone"], 0))["zone"]
            if hunters > 2:
                f.write("%s: flee %s (%d hunters) -> %s\n" % (day["day"], day["zone"], hunters, target))
            else:
                f.write("%s: hold %s (%d hunters)\n" % (day["day"], day["zone"], hunters))


def write_activity_log(path, members, forecast, deficit):
    duties = ["hunt", "guard the crypt", "scout the sewers", "tend the bats"]
    with open(path, "w") as f:
        for index, day in enumerate(forecast):
            member = members[index % len(members)]
            duty = duties[0] if deficit > 0 and day["cloud"] >= 70 else duties[(index + 1) % len(duties)]
            f.write("%s - %s (%s): %s\n" % (day["day"], member["name"], member["rank"], duty))


