    weekly_need = sum(m["need"] for m in members) * max(len(forecast), 1)
    write_safe_zones(os.path.join(folder, "safe_hunting_zones.txt"), forecast)
    deficit = 0.0
    if sum(reserves.values()) < weekly_need:
        deficit = write_warning(os.path.join(folder, "low_reserve_warning.txt"), reserves, weekly_need)
    sightings = read_sightings(os.path.join(folder, "hunter_sightings.txt"))
    write_relocation(os.path.join(folder, "relocation_strategy.txt"), forecast, sightings)
    write_activity_log(os.path.join(folder, "nightly_activity_log.txt"), members, forecast, deficit)
    return deficit


