            if hero["available"] and hero["name"] not in used and hero["power"] == wanted:
                pick = hero
                break
        if pick:
            used.add(pick["name"])
        assignments.append({"threat": threat, "hero": pick, "level": level,
                            "villain": villain["name"] if villain else ""})
    reserves = [h for h in heroes if h["name"] not in used]
    return assignments, reserves


def write_deployment(path, assignments, budgets):
    f = open(path, "w", encoding="utf-8")
    for a in assignments:
        t = a["threat"]
        budget = budgets.get(t["district"], 0.0)
        hero = a["hero"]["name"] if a["hero"] else "UNASSIGNED"
        f.write("{} | sector {} | {} lvl {} | {} | budget {:.2f}\n".format(
            t["district"], t["sector"], t["kind"], a["level"], hero, budget))
    f.close()


def write_reserves(path, reserves):
    f = open(path, "w", encoding="utf-8")
    for hero in reserves:
        state = "ready" if hero["available"] else "off-duty"
        f.write("{} ({}) - {}\n".format(hero["name"], hero["power"], state))
    f.close()


def write_broadcast(path, assignments):
    f = open(path, "w", encoding="utf-8")
    for a in assignments:
        if a["level"] >= 5:
            t = a["threat"]
            f.write("EVACUATE {} sector {}: {} threat level {}{}\n".format(
                t["district"], t["sector"], t["kind"], a["level"],
                " - villain " + a["villain"] if a["villain"] else ""))
    f.close()


def write_probabilities(path, assignments):
    f = open(path, "w", encoding="utf-8")
    total = 0.0
    for a in assignments:
        chance = 0.15 if a["hero"] is None else max(0.2, 1.0 - 0.09 * a["level"])
        total += chance
        f.write("{}/{}: {:.0%}\n".format(a["threat"]["district"],
                                         a["threat"]["sector"], chance))
    if assignments:
        f.write("overall: {:.0%}\n".format(total / len(assignments)))
    f.close()


def dispatch(folder):
    heroes = load_heroes(os.path.join(folder, "hero_roster.txt"))
    threats = load_threats(os.path.join(folder, "threat_map.txt"))
    budgets = load_budgets(os.path.join(folder, "damage_budget.txt"))
    villains = load_villains(os.path.join(folder, "villain_tracking.txt"))
    assignments, reserves = match(heroes, threats, villains)
    write_deployment(os.path.join(folder, "deployment_roster.txt"), assignments, budgets)
    write_reserves(os.path.join(folder, "standby_reserves.txt"), reserves)
    write_broadcast(os.path.join(folder, "evacuation_broadcast.txt"), assignments)
    write_probabilities(os.path.join(folder, "mission_probability.txt"), assignments)
    return assignments


if __name__ == "__main__":
    import sys
    for row in dispatch(sys.argv[1] if len(sys.argv) > 1 else "."):
        print(row["threat"]["district"], row["hero"]["name"] if row["hero"] else "-")

