import os


def read_registry(path):
    rooms = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = [p.strip() for p in line.split("|")]
            if len(parts) == 3 and parts[0].lower() != "room":
                rooms[parts[0]] = {"year": parts[1], "history": parts[2]}
    return rooms


def read_emf(path):
    spikes = {}
    drained = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = [p.strip() for p in line.split("|")]
            if len(parts) != 4 or parts[0].lower() == "room":
                continue
            room, stamp, reading, battery = parts[0], parts[1], float(parts[2]), int(parts[3])
            if reading >= 100.0:
                spikes[(room, stamp)] = reading
            if battery <= 20:
                drained.append((room, stamp, battery))
    return spikes, drained


def read_thermal(path):
    drops = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = [p.strip() for p in line.split("|")]
            if len(parts) == 3 and parts[0].lower() != "room":
                temp = float(parts[2])
                if temp <= 5.0:
                    drops[(parts[0], parts[1])] = temp
    return drops


def match_entities(path, history):
    entities = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = [p.strip() for p in line.split("|")]
            if len(parts) == 2 and parts[0].lower() in history.lower():
                entities.append(parts[1])
    return entities or ["unidentified presence"]


def track(folder):
    rooms = read_registry(os.path.join(folder, "haunted_registry.txt"))
    spikes, drained = read_emf(os.path.join(folder, "emf_readings.txt"))
    drops = read_thermal(os.path.join(folder, "cold_spots.txt"))
    folklore = os.path.join(folder, "folklore_archive.txt")

    confirmed = []
    for key in sorted(set(spikes) & set(drops)):
        room, stamp = key
        history = rooms.get(room, {}).get("history", "")
        confirmed.append((room, stamp, spikes[key], drops[key], match_entities(folklore, history)))

    haunted_rooms = {c[0] for c in confirmed}
    with open(os.path.join(folder, "confirmed_hauntings.txt"), "w", encoding="utf-8") as f:
        for room, stamp, emf, temp, entities in confirmed:
            f.write("%s | %s | EMF %.1f uT | %.1f C | %s\n" % (room, stamp, emf, temp, ", ".join(entities)))

    with open(os.path.join(folder, "debunked_myths.txt"), "w", encoding="utf-8") as f:
        for room in sorted(r for r in rooms if r not in haunted_rooms):
            f.write("%s (since %s) | no correlated anomaly | %s\n" % (room, rooms[room]["year"], rooms[room]["history"]))

    with open(os.path.join(folder, "equipment_maintenance.txt"), "w", encoding="utf-8") as f:
        for room, stamp, battery in drained:
            f.write("Recharge meter used in %s at %s (battery %d%%)\n" % (room, stamp, battery))

    with open(os.path.join(folder, "paranormal_activity_report.txt"), "w", encoding="utf-8") as f:
        f.write("Locations surveyed: %d\n" % len(rooms))
        f.write("Confirmed hauntings: %d\n" % len(confirmed))
        f.write("Debunked locations: %d\n" % (len(rooms) - len(haunted_rooms)))
        f.write("Battery incidents: %d\n" % len(drained))
        for room, stamp, emf, temp, entities in confirmed:
            f.write("  %s at %s -> %s\n" % (room, stamp, "/".join(entities)))

    return confirmed


