import os

MIN_HORSEPOWER = 600
TIRE_RANK = {"small": 1, "medium": 2, "large": 3}


def read_vehicles(path):
    trucks = []
    with open(path, "r") as f:
        for line in f:
            parts = [p.strip() for p in line.split(",")]
            if len(parts) == 3:
                trucks.append({"name": parts[0], "tire": parts[1].lower(), "hp": int(parts[2])})
    return trucks


def read_track(path):
    track = {"jumps": [], "mud_tire": "small"}
    with open(path, "r") as f:
        for line in f:
            key, _, value = line.partition(":")
            key = key.strip().lower()
            value = value.strip()
            if key == "jump":
                track["jumps"].append(value)
            elif key == "mud_pit_tire":
                track["mud_tire"] = value.lower()
    return track


def read_fireworks(path):
    shows = []
    with open(path, "r") as f:
        for line in f:
            name, _, minute = line.partition("@")
            if minute.strip():
                shows.append((int(minute.strip()), name.strip()))
    return sorted(shows)


def read_tickets(path):
    buyers = []
    with open(path, "r") as f:
        for line in f:
            parts = [p.strip() for p in line.split(",")]
            if len(parts) == 3:
                buyers.append((parts[0], parts[1], float(parts[2])))
    return buyers


def plan(folder):
    trucks = read_vehicles(os.path.join(folder, "vehicle_specifications.txt"))
    track = read_track(os.path.join(folder, "dirt_track_layout.txt"))
    shows = read_fireworks(os.path.join(folder, "pyrotechnics_schedule.txt"))
    buyers = read_tickets(os.path.join(folder, "ticket_sales.txt"))

    needed = TIRE_RANK.get(track["mud_tire"], 1)
    cleared, repairs = [], []
    for truck in trucks:
        problems = []
        if TIRE_RANK.get(truck["tire"], 0) < needed:
            problems.append("needs %s tires for mud pit" % track["mud_tire"])
        if truck["hp"] < MIN_HORSEPOWER:
            problems.append("horsepower %d below %d" % (truck["hp"], MIN_HORSEPOWER))
        if problems:
            repairs.append((truck["name"], problems))
        else:
            cleared.append(truck)

    with open(os.path.join(folder, "cleared_to_race.txt"), "w") as f:
        for truck in cleared:
            f.write("%s | %s tires | %d hp\n" % (truck["name"], truck["tire"], truck["hp"]))

    with open(os.path.join(folder, "mechanical_repairs.txt"), "w") as f:
        for name, problems in repairs:
            f.write("%s: %s\n" % (name, "; ".join(problems)))

    vips = sorted([b for b in buyers if b[1].lower() == "vip"], key=lambda b: -b[2])
    with open(os.path.join(folder, "vip_seating_chart.txt"), "w") as f:
        for row, (name, _, price) in enumerate(vips, start=1):
            f.write("Row A Seat %d - %s ($%.2f)\n" % (row, name, price))

    timetable = []
    for index, truck in enumerate(cleared):
        jump = track["jumps"][index % len(track["jumps"])] if track["jumps"] else "flat course"
        timetable.append((index * 15, "Race: %s over %s" % (truck["name"], jump)))
    timetable.extend((minute, "Fireworks: %s" % name) for minute, name in shows)

    with open(os.path.join(folder, "final_event_timetable.txt"), "w") as f:
        for minute, entry in sorted(timetable):
            f.write("T+%03d min  %s\n" % (minute, entry))

    return {"cleared": len(cleared), "repairs": len(repairs), "vips": len(vips)}


if __name__ == "__main__":
    print(plan("event_data"))

