import os


def read_lineage(path):
    dragons = {}
    with open(path, "r") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            name, color, sire, dam = [p.strip() for p in line.split(",")]
            dragons[name] = {"color": color, "sire": sire, "dam": dam}
    return dragons


def read_breath(path):
    breath = {}
    with open(path, "r") as f:
        for line in f:
            if "=" in line:
                color, weapon = line.split("=", 1)
                breath[color.strip()] = weapon.strip()
    return breath


def read_mutations(path):
    blends = {}
    with open(path, "r") as f:
        for line in f:
            if "->" in line:
                parents, child = line.split("->", 1)
                pair = frozenset(p.strip() for p in parents.split("+"))
                blends[pair] = child.strip()
    return blends


def read_meat(path):
    meat = {}
    with open(path, "r") as f:
        for line in f:
            if ":" in line:
                color, kilos = line.split(":", 1)
                meat[color.strip()] = float(kilos.strip())
    return meat


def ancestors(dragons, name, depth=3):
    if depth == 0 or name not in dragons:
        return set()
    parents = {dragons[name]["sire"], dragons[name]["dam"]} - {"unknown"}
    found = set(parents)
    for parent in parents:
        found |= ancestors(dragons, parent, depth - 1)
    return found


def pair_dragons(dragons):
    names = sorted(dragons)
    return [(names[i], names[i + 1]) for i in range(0, len(names) - 1, 2)]


def breed(folder):
    dragons = read_lineage(os.path.join(folder, "lineage.txt"))
    breath = read_breath(os.path.join(folder, "breath_genetics.txt"))
    blends = read_mutations(os.path.join(folder, "scale_mutations.txt"))
    meat = read_meat(os.path.join(folder, "meat_consumption.txt"))

    pairs = pair_dragons(dragons)
    hatchlings = []
    warnings = []
    for sire, dam in pairs:
        c1, c2 = dragons[sire]["color"], dragons[dam]["color"]
        scales = blends.get(frozenset((c1, c2)), c1 if c1 == c2 else "grey")
        weapon = breath.get(scales, "steam")
        hatchlings.append((sire, dam, scales, weapon))
        shared = ancestors(dragons, sire) & ancestors(dragons, dam)
        if shared or sire in ancestors(dragons, dam) or dam in ancestors(dragons, sire):
            warnings.append((sire, dam, sorted(shared) or ["direct descent"]))

    with open(os.path.join(folder, "hatchling_traits.txt"), "w") as f:
        for sire, dam, scales, weapon in hatchlings:
            f.write("%s x %s -> %s scales, %s breath\n" % (sire, dam, scales, weapon))

    with open(os.path.join(folder, "inbreeding_warnings.txt"), "w") as f:
        for sire, dam, shared in warnings:
            f.write("WARNING %s x %s shares: %s\n" % (sire, dam, ", ".join(shared)))

    total = sum(meat.get(d["color"], 20.0) for d in dragons.values())
    total += sum(meat.get(h[2], 20.0) / 4 for h in hatchlings)
    with open(os.path.join(folder, "livestock_order.txt"), "w") as f:
        f.write("Daily meat requirement: %.1f kg\n" % total)
        f.write("Cattle (400 kg each): %d\n" % -(-int(total * 7) // 400))
        f.write("Goats (35 kg each): %d\n" % -(-int(total) // 35))

    unpaired = [n for n in sorted(dragons) if all(n not in p for p in pairs)]
    with open(os.path.join(folder, "auction_catalog.txt"), "w") as f:
        f.write("UPCOMING DRAGON AUCTION\n")
        for name in unpaired:
            color = dragons[name]["color"]
            f.write("Lot: %s (%s, %s breath) - reserve %d gp\n" %
                    (name, color, breath.get(color, "steam"), 500 + len(color) * 50))
        for sire, dam, scales, weapon in warnings and [] or hatchlings:
            f.write("Egg: %s x %s, expected %s scales, %s breath\n" % (sire, dam, scales, weapon))

    return {"hatchlings": hatchlings, "warnings": warnings, "meat_kg": total}


if __name__ == "__main__":
    import sys
    report = breed(sys.argv[1] if len(sys.argv) > 1 else ".")
    print("%d pairings, %d warnings, %.1f kg/day" %
          (len(report["hatchlings"]), len(report["warnings"]), report["meat_kg"]))

