import math
import struct

EARTH_RADIUS_KM = 6371.0
CRUISE_SPEED_KMH = 820.0
FUEL_PER_KM = 3.2
EMISSION_FACTOR = 3.16


def read_boundaries(path):
    ceilings = {}
    with open(path, "r") as boundaries_file:
        for line in boundaries_file:
            parts = line.split()
            if len(parts) == 2:
                ceilings[parts[0]] = float(parts[1])
    return ceilings


def read_beacons(path):
    beacons = []
    with open(path, "r") as beacon_file:
        for line in beacon_file:
            parts = line.split()
            if len(parts) == 3:
                beacons.append((parts[0], float(parts[1]), float(parts[2])))
    return beacons


def read_weather(path):
    winds = {}
    with open(path, "r") as weather_file:
        for line in weather_file:
            parts = line.split()
            if len(parts) == 2:
                winds[parts[0]] = float(parts[1])
    return winds


def leg_distance(first, second):
    lat1, lon1 = math.radians(first[1]), math.radians(first[2])
    lat2, lon2 = math.radians(second[1]), math.radians(second[2])
    inner = math.sin((lat2 - lat1) / 2) ** 2 + math.cos(lat1) * math.cos(lat2) * math.sin((lon2 - lon1) / 2) ** 2
    return 2 * EARTH_RADIUS_KM * math.asin(math.sqrt(inner))


def convert(flights):
    ceilings = read_boundaries("airspace_boundaries.txt")
    beacons = read_beacons("beacon_locations.txt")
    ceiling = min(ceilings.values())
    trajectories = {}
    with open("flight_path.bin", "wb") as path_file:
        with open("schedule.txt", "w") as schedule_file:
            for index, code in enumerate(flights):
                offset = index * 0.35
                legs = [(name, lat + offset, lon - offset) for name, lat, lon in beacons]
                trajectories[code] = legs
                for name, lat, lon in legs:
                    path_file.write(struct.pack("<ff f".replace(" ", ""), lat, lon, ceiling))
                distance = sum(leg_distance(legs[i], legs[i + 1]) for i in range(len(legs) - 1))
                schedule_file.write("%s %.2f\n" % (code, distance / CRUISE_SPEED_KMH))

    winds = read_weather("weather_conditions.txt")
    with open("fuel_consumption.txt", "w") as fuel_file:
        for code, legs in trajectories.items():
            adjusted = 0.0
            for i in range(len(legs) - 1):
                headwind = winds.get(legs[i][0], 0.0)
                adjusted += leg_distance(legs[i], legs[i + 1]) * (1.0 + headwind / 100.0)
            fuel_file.write("%s %.3f\n" % (code, adjusted * FUEL_PER_KM))

    codes = list(trajectories)
    overlaps = []
    for i in range(len(codes)):
        for j in range(i + 1, len(codes)):
            for first, second in zip(trajectories[codes[i]], trajectories[codes[j]]):
                if leg_distance(first, second) < 8.0:
                    overlaps.append((codes[i], codes[j], first[0]))
    if overlaps:
        with open("collision_warning.txt", "w") as warning_file:
            for left, right, beacon in overlaps:
                warning_file.write("CONFLICT %s %s near %s\n" % (left, right, beacon))

    total_emissions = 0.0
    with open("fuel_consumption.txt", "r") as fuel_file:
        for line in fuel_file:
            total_emissions += float(line.split()[1]) * EMISSION_FACTOR

    with open("daily_operations_summary.txt", "w") as summary_file:
        summary_file.write("flights: %d\n" % len(flights))
        summary_file.write("conflicts: %d\n" % len(overlaps))
        summary_file.write("emissions_kg: %.3f\n" % total_emissions)
    return total_emissions


def main():
    with open("flights.txt", "r") as flight_list:
        flights = [line.strip() for line in flight_list if line.strip()]
    print("total emissions: %.3f kg" % convert(flights))


if __name__ == "__main__":
    main()

