import math
import sys


def load_config(config_path):
    precision = 6
    with open(config_path, encoding="utf-8") as config:
        for raw in config:
            line = raw.split("#", 1)[0].strip()
            if line:
                key, value = line.split("=", 1)
                if key.strip() == "precision":
                    precision = int(value.strip())
    return precision


def load_paths(manifest_path):
    paths = []
    with open(manifest_path, encoding="utf-8") as manifest:
        for raw in manifest:
            entry = raw.strip()
            if entry and not entry.startswith("#"):
                paths.append(entry)
    return paths


def parse_series(data_path):
    values = []
    with open(data_path, encoding="utf-8") as data:
        for raw in data:
            body = raw.split("#", 1)[0].replace(",", " ")
            for token in body.split():
                try:
                    values.append(float(token))
                except ValueError:
                    raise ValueError("%s: %r is not a number" % (data_path, token))
    return values


def geometric_mean(numbers):
    """Return the Nth root of the product of N positive numbers."""
    values = list(numbers)
    if not values:
        raise ValueError("geometric mean is undefined for an empty sequence")
    for value in values:
        if value <= 0:
            raise ValueError("all numbers must be positive, got %r" % (value,))
    total = math.fsum(math.log(float(value)) for value in values)
    return math.exp(total / len(values))


def write_report(report_path, records, precision):
    with open(report_path, "w", encoding="utf-8") as report:
        report.write("geometric mean report\n")
        report.write("=" * 21 + "\n")
        for path, count, mean in records:
            report.write("%-30s n=%-4d mean=%.*f\n" % (path, count, precision, mean))


def write_csv(csv_path, records, precision):
    with open(csv_path, "w", encoding="utf-8") as out:
        out.write("path,count,geometric_mean\n")
        for path, count, mean in records:
            out.write("%s,%d,%.*f\n" % (path, count, precision, mean))


def append_log(log_path, message):
    with open(log_path, "a", encoding="utf-8") as log:
        log.write(message + "\n")


def main(argv):
    if len(argv) != 6:
        print("usage: %s CONFIG MANIFEST REPORT CSV LOG" % argv[0])
        return 2
    config_path, manifest_path, report_path, csv_path, log_path = argv[1:]
    precision = load_config(config_path)
    records = []
    for data_path in load_paths(manifest_path):
        try:
            values = parse_series(data_path)
            records.append((data_path, len(values), geometric_mean(values)))
        except (OSError, ValueError) as exc:
            append_log(log_path, "FAILED %s: %s" % (data_path, exc))
    write_report(report_path, records, precision)
    write_csv(csv_path, records, precision)
    append_log(log_path, "wrote %d row(s) to %s" % (len(records), report_path))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

