import os
import sys
from collections import Counter

DEFAULT_CONFIG = {
    "input": "numbers.txt",
    "report": "digit_sums.txt",
    "errors": "digit_errors.txt",
    "histogram": "digit_histogram.txt",
}


def sum_digits(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    total = 0
    while n >= 10:
        total += n % 10
        n //= 10
    return total + n


def load_config(path):
    config = dict(DEFAULT_CONFIG)
    if os.path.exists(path):
        with open(path, encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                key, _, value = line.partition("=")
                key = key.strip()
                if key in config:
                    config[key] = value.strip()
    return config


def parse_numbers(path):
    values = []
    errors = []
    with open(path, encoding="utf-8") as f:
        for lineno, line in enumerate(f, start=1):
            token = line.strip()
            if not token:
                continue
            if token.isdigit():
                values.append(int(token))
            else:
                errors.append((lineno, token))
    return values, errors


def write_report(path, values):
    with open(path, "w", encoding="utf-8") as f:
        f.write("number\tdigit_sum\n")
        for value in values:
            f.write("{}\t{}\n".format(value, sum_digits(value)))
        f.write("count\t{}\n".format(len(values)))


def write_errors(path, errors):
    with open(path, "w", encoding="utf-8") as f:
        for lineno, token in errors:
            f.write("line {}: not a non-negative integer: {!r}\n".format(lineno, token))


def write_histogram(path, values):
    counts = Counter(sum_digits(value) for value in values)
    with open(path, "w", encoding="utf-8") as f:
        for digit_sum in sorted(counts):
            f.write("{:>3} | {}\n".format(digit_sum, "*" * counts[digit_sum]))


def main(argv):
    config = load_config(argv[1] if len(argv) > 1 else "digits.ini")
    if not os.path.exists(config["input"]):
        print("input file not found:", config["input"])
        return 1
    values, errors = parse_numbers(config["input"])
    write_report(config["report"], values)
    write_histogram(config["histogram"], values)
    if errors:
        write_errors(config["errors"], errors)
        print("skipped {} bad line(s); see {}".format(len(errors), config["errors"]))
    print("wrote digit sums for {} number(s) to {}".format(len(values), config["report"]))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

