import json
import os
import sys


KNOWN_STATUSES = {
    200: 'OK',
    404: 'Not Found',
    500: 'Internal Server Error',
}


def check_http_status(status_code):
    return KNOWN_STATUSES.get(status_code, 'Unknown Status')


def parse_status(line):
    fields = line.split()
    if len(fields) < 9:
        return None
    try:
        return int(fields[8])
    except ValueError:
        return None


def summarize_log(log_path):
    counts = {}
    with open(log_path, encoding='utf-8') as log_file:
        for line in log_file:
            status = parse_status(line)
            if status is not None:
                counts[status] = counts.get(status, 0) + 1
    return counts


def write_report(counts, report_path):
    with open(report_path, 'w', encoding='utf-8') as report_file:
        report_file.write('status  description            hits\n')
        for status in sorted(counts):
            description = check_http_status(status)
            report_file.write('{:<7} {:<22} {:>5}\n'.format(status, description, counts[status]))
        report_file.write('total   {:>28}\n'.format(sum(counts.values())))


def write_counts_csv(counts, csv_path):
    with open(csv_path, 'w', encoding='utf-8') as csv_file:
        csv_file.write('status,description,hits\n')
        for status in sorted(counts):
            csv_file.write('{},"{}",{}\n'.format(status, check_http_status(status), counts[status]))


def write_counts_json(counts, json_path):
    payload = [
        {'status': status, 'description': check_http_status(status), 'hits': counts[status]}
        for status in sorted(counts)
    ]
    with open(json_path, 'w', encoding='utf-8') as json_file:
        json.dump({'statuses': payload, 'total': sum(counts.values())}, json_file, indent=2)


def append_history(history_path, log_name, counts):
    errors = sum(hits for status, hits in counts.items() if status >= 400)
    with open(history_path, 'a', encoding='utf-8') as history_file:
        history_file.write('{} hits={} errors={}\n'.format(log_name, sum(counts.values()), errors))


def merge(target, source):
    for status, hits in source.items():
        target[status] = target.get(status, 0) + hits


def main(argv):
    if not argv:
        print('usage: python http_status.py ACCESS_LOG [ACCESS_LOG ...]')
        return 1
    totals = {}
    for log_path in argv:
        counts = summarize_log(log_path)
        merge(totals, counts)
        base = os.path.splitext(log_path)[0]
        write_report(counts, base + '.report.txt')
        append_history('status_history.txt', os.path.basename(log_path), counts)
    write_counts_csv(totals, 'status_totals.csv')
    write_counts_json(totals, 'status_totals.json')
    for status in sorted(totals):
        print('{} {} -> {}'.format(status, check_http_status(status), totals[status]))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))

