import math
import os
import sys


def calculate_std_dev(numbers):
    n = len(numbers)
    mean = sum(numbers) / n
    variance = sum((x - mean) ** 2 for x in numbers) / (n - 1)
    return math.sqrt(variance)


def read_manifest(path):
    paths = []
    base = os.path.dirname(os.path.abspath(path))
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            entry = line.strip()
            if entry and not entry.startswith("#"):
                paths.append(entry if os.path.isabs(entry) else os.path.join(base, entry))
    return paths


def load_series(path):
    numbers = []
    with open(path, "r", encoding="utf-8") as f:
        for lineno, line in enumerate(f, start=1):
            token = line.split("#", 1)[0].strip()
            if not token:
                continue
            try:
                numbers.append(float(token))
            except ValueError:
                raise ValueError("%s:%d: not a number: %r" % (path, lineno, token))
    if len(numbers) < 2:
        raise ValueError("%s: need at least two values, got %d" % (path, len(numbers)))
    return numbers


def summarize(path):
    numbers = load_series(path)
    return {
        "label": os.path.basename(path),
        "count": len(numbers),
        "mean": sum(numbers) / len(numbers),
        "std_dev": calculate_std_dev(numbers),
    }


def write_report(path, rows):
    with open(path, "w", encoding="utf-8") as f:
        f.write("%-24s %6s %12s %12s\n" % ("series", "n", "mean", "std_dev"))
        for row in rows:
            f.write("%-24s %6d %12.4f %12.4f\n" % (row["label"], row["count"], row["mean"], row["std_dev"]))


def write_csv(path, rows):
    with open(path, "w", encoding="utf-8") as f:
        f.write("series,count,mean,std_dev\n")
        for row in rows:
            f.write("%s,%d,%.6f,%.6f\n" % (row["label"], row["count"], row["mean"], row["std_dev"]))


def append_log(path, message):
    with open(path, "a", encoding="utf-8") as f:
        f.write(message + "\n")


def main(argv):
    if len(argv) != 2:
        print("usage: %s MANIFEST" % os.path.basename(argv[0]), file=sys.stderr)
        return 2
    manifest = argv[1]
    rows = []
    for data_path in read_manifest(manifest):
        try:
            rows.append(summarize(data_path))
        except (OSError, ValueError) as exc:
            append_log("stddev.log", "skipped: %s" % exc)
    rows.sort(key=lambda row: row["std_dev"], reverse=True)
    write_report("stddev_report.txt", rows)
    write_csv("stddev_report.csv", rows)
    append_log("stddev.log", "processed %d series from %s" % (len(rows), manifest))
    for row in rows:
        print("%s: std_dev=%.3f" % (row["label"], row["std_dev"]))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

