import sys
import os


def product_list(numbers):
    product = 1
    for value in numbers:
        product *= value
    return product


def parse_line(line):
    values = []
    for token in line.replace(",", " ").split():
        text = token.strip()
        if "." in text or "e" in text.lower():
            values.append(float(text))
        else:
            values.append(int(text))
    return values


def read_manifest(path):
    sources = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            text = line.strip()
            if text and not text.startswith("#"):
                sources.append(text)
    return sources


def read_datasets(path):
    datasets = []
    problems = []
    with open(path, "r", encoding="utf-8") as f:
        for number, line in enumerate(f, start=1):
            if not line.strip():
                continue
            try:
                datasets.append((number, parse_line(line)))
            except ValueError:
                problems.append((number, line.strip()))
    return datasets, problems


def write_results(path, results):
    with open(path, "w", encoding="utf-8") as f:
        f.write("source\tline\tcount\tproduct\n")
        for source, number, values, product in results:
            f.write("{}\t{}\t{}\t{}\n".format(source, number, len(values), product))


def write_problem_log(path, problems):
    with open(path, "a", encoding="utf-8") as f:
        for source, number, text in problems:
            f.write("{} line {}: cannot parse {!r}\n".format(source, number, text))


def write_report(path, results, problems):
    zeros = sum(1 for item in results if item[3] == 0)
    negatives = sum(1 for item in results if item[3] < 0)
    with open(path, "w", encoding="utf-8") as f:
        f.write("datasets processed: {}\n".format(len(results)))
        f.write("zero products: {}\n".format(zeros))
        f.write("negative products: {}\n".format(negatives))
        f.write("skipped lines: {}\n".format(len(problems)))
        if results:
            largest = max(results, key=lambda item: item[3])
            f.write("largest product: {} ({} line {})\n".format(largest[3], largest[0], largest[1]))


def main(argv):
    manifest = argv[1] if len(argv) > 1 else "inputs.txt"
    if not os.path.exists(manifest):
        print("manifest not found: {}".format(manifest))
        return 1
    results = []
    problems = []
    for source in read_manifest(manifest):
        if not os.path.exists(source):
            print("skipping missing file: {}".format(source))
            continue
        datasets, issues = read_datasets(source)
        problems.extend((source, number, text) for number, text in issues)
        results.extend((source, number, values, product_list(values)) for number, values in datasets)
    write_results("products.tsv", results)
    if problems:
        write_problem_log("products.log", problems)
    write_report("products_report.txt", results, problems)
    for source, number, values, product in results:
        print("{} line {}: {} -> {}".format(source, number, values, product))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

