import json
import os
import sys

DEFAULT_PAIRS = {')': '(', ']': '[', '}': '{'}


def load_pairs(path):
    """Read a JSON object mapping each closing bracket to its opener."""
    with open(path, encoding='utf-8') as f:
        pairs = json.load(f)
    if not all(len(k) == 1 and len(v) == 1 for k, v in pairs.items()):
        raise ValueError('bracket pairs must map single characters')
    return pairs


def load_expressions(path):
    """Read one candidate bracket string per line, ignoring blank lines."""
    expressions = []
    with open(path, encoding='utf-8') as f:
        for line in f:
            text = line.strip()
            if text:
                expressions.append(text)
    return expressions


def is_brackets_balanced(s, pairs=None):
    pairs = pairs or DEFAULT_PAIRS
    openers = set(pairs.values())
    stack = []
    for ch in s:
        if ch in openers:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
        else:
            return False
    return not stack


def write_report(path, results):
    with open(path, 'w', encoding='utf-8') as f:
        for expression, balanced in results:
            f.write('{}\t{}\n'.format(expression, 'BALANCED' if balanced else 'UNBALANCED'))


def write_unbalanced(path, results):
    with open(path, 'w', encoding='utf-8') as f:
        for expression, balanced in results:
            if not balanced:
                f.write(expression + '\n')


def append_summary(path, source, results):
    total = len(results)
    good = sum(1 for _, balanced in results if balanced)
    with open(path, 'a', encoding='utf-8') as f:
        f.write('{}: {}/{} balanced\n'.format(source, good, total))
    return good, total


def main(argv):
    if len(argv) < 2:
        print('usage: brackets.py INPUT_FILE [PAIRS_JSON]')
        return 1
    source = argv[1]
    pairs = load_pairs(argv[2]) if len(argv) > 2 else DEFAULT_PAIRS
    expressions = load_expressions(source)
    results = [(e, is_brackets_balanced(e, pairs)) for e in expressions]
    base = os.path.splitext(source)[0]
    write_report(base + '.report.tsv', results)
    write_unbalanced(base + '.unbalanced.txt', results)
    good, total = append_summary('brackets.log', source, results)
    print('{} of {} expressions are balanced'.format(good, total))
    return 0 if good == total else 2


if __name__ == '__main__':
    sys.exit(main(sys.argv))

