import sys

VALUES = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}


def roman_to_int(roman_numeral):
    text = roman_numeral.strip().upper()
    if not text:
        raise ValueError('empty roman numeral')
    total = 0
    previous = 0
    for index in range(len(text) - 1, -1, -1):
        char = text[index]
        if char not in VALUES:
            raise ValueError('invalid character %r in %r' % (char, roman_numeral))
        value = VALUES[char]
        if value < previous:
            total -= value
        else:
            total += value
            previous = value
    if not 1 <= total <= 3999:
        raise ValueError('%r is outside the range 1..3999' % roman_numeral)
    return total


def load_numerals(path):
    numerals = []
    with open(path, encoding='utf-8') as handle:
        for line in handle:
            token = line.strip()
            if token:
                numerals.append(token)
    return numerals


def convert_file(input_path, output_path, error_path):
    numerals = load_numerals(input_path)
    failures = []
    with open(output_path, 'w', encoding='utf-8') as out:
        for numeral in numerals:
            try:
                out.write('%s\t%d\n' % (numeral, roman_to_int(numeral)))
            except ValueError as exc:
                failures.append('%s: %s' % (numeral, exc))
    with open(error_path, 'w', encoding='utf-8') as err:
        for message in failures:
            err.write(message + '\n')
    return len(numerals) - len(failures), len(failures)


def summarize(output_path, summary_path):
    values = []
    with open(output_path, encoding='utf-8') as results:
        for line in results:
            numeral, number = line.rstrip('\n').split('\t')
            values.append((numeral, int(number)))
    with open(summary_path, 'w', encoding='utf-8') as summary:
        summary.write('converted: %d\n' % len(values))
        if values:
            smallest = min(values, key=lambda pair: pair[1])
            largest = max(values, key=lambda pair: pair[1])
            summary.write('smallest: %s = %d\n' % smallest)
            summary.write('largest: %s = %d\n' % largest)
            summary.write('sum: %d\n' % sum(value for _, value in values))
    return len(values)


def main(argv):
    if len(argv) != 2:
        print('usage: %s INPUT_FILE' % argv[0])
        return 2
    input_path = argv[1]
    ok, bad = convert_file(input_path, 'numbers.tsv', 'errors.log')
    total = summarize('numbers.tsv', 'summary.txt')
    print('converted %d numerals (%d rejected), summarized %d' % (ok, bad, total))
    return 1 if bad else 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

