import json
import sys
from datetime import datetime


def calculate_discount_price(original_price, discount_percentage):
    if original_price < 0:
        raise ValueError("original_price must not be negative")
    if not 0 <= discount_percentage <= 100:
        raise ValueError("discount_percentage must be between 0 and 100")
    return round(original_price * (1 - discount_percentage / 100.0), 2)


def load_discount_rules(path):
    with open(path, encoding="utf-8") as handle:
        rules = json.load(handle)
    cleaned = {}
    for category, percentage in rules.items():
        value = float(percentage)
        if not 0 <= value <= 100:
            raise ValueError("bad discount for category " + repr(category))
        cleaned[category.strip().lower()] = value
    return cleaned


def parse_catalog(path):
    with open(path, encoding="utf-8") as handle:
        lines = handle.readlines()
    items = []
    for number, line in enumerate(lines, start=1):
        row = line.strip()
        if not row or row.startswith("#"):
            continue
        fields = [part.strip() for part in row.split(",")]
        if len(fields) != 3:
            raise ValueError("line {} must have 3 fields".format(number))
        items.append((fields[0], fields[1].lower(), float(fields[2])))
    return items


def price_items(items, rules, default_percentage=0.0):
    priced = []
    for name, category, price in items:
        percentage = rules.get(category, default_percentage)
        final = calculate_discount_price(price, percentage)
        priced.append((name, category, price, percentage, final))
    return priced


def format_row(row):
    return "{:<20} {:<12} {:>8.2f} -{:>5.1f}% -> {:>8.2f}\n".format(*row)


def csv_row(row):
    return "{},{},{:.2f},{:.1f},{:.2f}\n".format(*row)


def write_report(path, priced):
    stamp = datetime.now().strftime("%Y-%m-%d %H:%M")
    gross = sum(row[2] for row in priced)
    net = sum(row[4] for row in priced)
    with open(path, "w", encoding="utf-8") as handle:
        handle.write("Discount report {}\n\n".format(stamp))
        for row in priced:
            handle.write(format_row(row))
        handle.write("\nTotal before discounts: {:.2f}\n".format(gross))
        handle.write("Total after discounts:  {:.2f}\n".format(net))
        handle.write("Customer saves:         {:.2f}\n".format(round(gross - net, 2)))


def write_csv(path, priced):
    with open(path, "w", encoding="utf-8") as handle:
        handle.write("name,category,original_price,discount_percentage,final_price\n")
        for row in priced:
            handle.write(csv_row(row))


def append_log(path, message):
    with open(path, "a", encoding="utf-8") as handle:
        handle.write(datetime.now().isoformat(timespec="seconds") + " " + message + "\n")


def main(argv):
    if len(argv) != 3:
        print("usage: {} CATALOG.csv RULES.json".format(argv[0]))
        return 1
    rules = load_discount_rules(argv[2])
    priced = price_items(parse_catalog(argv[1]), rules)
    write_report("report.txt", priced)
    write_csv("prices.csv", priced)
    append_log("run.log", "priced {} items using {} rules".format(len(priced), len(rules)))
    for row in priced:
        print(format_row(row).rstrip())
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

