TO_CELSIUS = {
    "C": lambda v: v,
    "F": lambda v: (v - 32.0) * 5.0 / 9.0,
    "K": lambda v: v - 273.15,
}
FROM_CELSIUS = {
    "C": lambda c: c,
    "F": lambda c: c * 9.0 / 5.0 + 32.0,
    "K": lambda c: c + 273.15,
}


def convert_temperature(value, unit_from, unit_to):
    celsius = TO_CELSIUS[unit_from](float(value))
    return float(FROM_CELSIUS[unit_to](celsius))


def read_requests(path):
    requests = []
    errors = []
    with open(path, encoding="utf-8") as f:
        for lineno, raw in enumerate(f, 1):
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            parts = [p.strip() for p in line.split(",")]
            if len(parts) != 3:
                errors.append("line %d: expected 3 fields, got %d" % (lineno, len(parts)))
                continue
            try:
                value = float(parts[0])
            except ValueError:
                errors.append("line %d: %r is not a number" % (lineno, parts[0]))
                continue
            unit_from, unit_to = parts[1].upper(), parts[2].upper()
            if unit_from not in TO_CELSIUS or unit_to not in FROM_CELSIUS:
                errors.append("line %d: unknown unit in %r" % (lineno, line))
                continue
            requests.append((value, unit_from, unit_to))
    return requests, errors


def write_results_csv(path, results):
    with open(path, "w", encoding="utf-8") as f:
        f.write("value,unit_from,result,unit_to\n")
        for value, unit_from, result, unit_to in results:
            f.write("%.4f,%s,%.4f,%s\n" % (value, unit_from, result, unit_to))


def write_report(path, results):
    with open(path, "w", encoding="utf-8") as f:
        f.write("%12s %4s %12s %4s\n" % ("input", "from", "output", "to"))
        for value, unit_from, result, unit_to in results:
            f.write("%12.3f %4s %12.3f %4s\n" % (value, unit_from, result, unit_to))


def append_errors(path, errors):
    with open(path, "a", encoding="utf-8") as f:
        for message in errors:
            f.write(message + "\n")


def write_summary(path, results):
    per_unit = {}
    for _value, _unit_from, result, unit_to in results:
        per_unit.setdefault(unit_to, []).append(result)
    with open(path, "w", encoding="utf-8") as f:
        f.write("conversions: %d\n" % len(results))
        for unit in sorted(per_unit):
            values = per_unit[unit]
            f.write("%s: count=%d min=%.2f max=%.2f\n"
                    % (unit, len(values), min(values), max(values)))


def main(argv):
    source = argv[1] if len(argv) > 1 else "requests.txt"
    requests, errors = read_requests(source)
    results = [(v, uf, convert_temperature(v, uf, ut), ut) for v, uf, ut in requests]
    write_results_csv("results.csv", results)
    write_report("report.txt", results)
    write_summary("summary.txt", results)
    if errors:
        append_errors("errors.log", errors)
        print("%d malformed line(s) logged to errors.log" % len(errors))
    print("wrote %d conversion(s) to results.csv and report.txt" % len(results))
    return 0 if not errors else 1


if __name__ == "__main__":
    import sys
    raise SystemExit(main(sys.argv))

