import json
import sys
from datetime import datetime


def filter_dict_by_value(data_dict, min_value):
    return {key: value for key, value in data_dict.items() if value >= min_value}


def load_scores(path):
    scores = {}
    with open(path, "r", encoding="utf-8") as f:
        for line_number, line in enumerate(f, start=1):
            stripped = line.strip()
            if not stripped or stripped.startswith("#"):
                continue
            parts = stripped.split(",")
            if len(parts) != 2:
                raise ValueError("%s:%d: expected 'key,value'" % (path, line_number))
            key, raw_value = parts[0].strip(), parts[1].strip()
            try:
                scores[key] = float(raw_value) if "." in raw_value else int(raw_value)
            except ValueError:
                raise ValueError("%s:%d: bad number %r" % (path, line_number, raw_value))
    return scores


def load_threshold(path):
    with open(path, "r", encoding="utf-8") as f:
        config = json.load(f)
    return config["min_value"]


def merge_sources(paths):
    merged = {}
    for path in paths:
        for key, value in load_scores(path).items():
            if key in merged:
                merged[key] = max(merged[key], value)
            else:
                merged[key] = value
    return merged


def save_filtered(path, filtered):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(filtered, f, indent=2, sort_keys=True)
        f.write("\n")


def write_report(path, merged, filtered, min_value):
    dropped = len(merged) - len(filtered)
    with open(path, "w", encoding="utf-8") as f:
        f.write("threshold: %s\n" % min_value)
        f.write("kept %d of %d entries (%d dropped)\n" % (len(filtered), len(merged), dropped))
        for key, value in sorted(filtered.items(), key=lambda item: (-item[1], item[0])):
            f.write("  %-12s %s\n" % (key, value))


def append_log(path, min_value, kept):
    with open(path, "a", encoding="utf-8") as f:
        f.write("%s kept=%d threshold=%s\n" % (datetime.now().isoformat(timespec="seconds"), kept, min_value))


def main(argv):
    if len(argv) < 2:
        print("usage: filter_scores.py config.json data.csv [data.csv ...]", file=sys.stderr)
        return 2
    min_value = load_threshold(argv[0])
    merged = merge_sources(argv[1:])
    filtered = filter_dict_by_value(merged, min_value)
    save_filtered("filtered.json", filtered)
    write_report("filter_report.txt", merged, filtered, min_value)
    append_log("filter_history.log", min_value, len(filtered))
    print("kept %d of %d entries" % (len(filtered), len(merged)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

