def reverse_integer(n):
    """Reverse the digits of an integer, preserving its sign."""
    sign = -1 if n < 0 else 1
    return sign * int(str(abs(n))[::-1])


def parse_integer(text):
    """Convert a line of text to an int, raising ValueError on bad input."""
    cleaned = text.strip().replace("_", "")
    if not cleaned:
        raise ValueError("empty value")
    return int(cleaned)


def read_integers(path):
    """Read one integer per line, returning values and rejected lines."""
    values = []
    rejected = []
    with open(path, encoding="utf-8") as f:
        for lineno, line in enumerate(f, start=1):
            if not line.strip():
                continue
            try:
                values.append(parse_integer(line))
            except ValueError:
                rejected.append((lineno, line.rstrip("\n")))
    return values, rejected


def write_reversed(path, pairs):
    """Write 'original -> reversed' for each processed value."""
    with open(path, "w", encoding="utf-8") as f:
        for original, reversed_value in pairs:
            f.write("{} -> {}\n".format(original, reversed_value))


def write_rejects(path, rejected):
    """Record lines that could not be parsed as integers."""
    with open(path, "w", encoding="utf-8") as f:
        for lineno, raw in rejected:
            f.write("line {}: {!r}\n".format(lineno, raw))


