import sys


def calculate_sample_std_dev(numbers):
    count = len(numbers)
    if count < 2:
        return 0.0
    mean = sum(numbers) / count
    variance = sum((value - mean) ** 2 for value in numbers) / (count - 1)
    return variance ** 0.5


def read_manifest(path):
    paths = []
    with open(path, "r", encoding="utf-8") as handle:
        for raw in handle:
            entry = raw.strip()
            if entry and not entry.startswith("#"):
                paths.append(entry)
    return paths


def read_series(path):
    series = {}
    errors = []
    with open(path, "r", encoding="utf-8") as handle:
        for line_no, raw in enumerate(handle, start=1):
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            if ":" not in line:
                errors.append("%s line %d: missing ':' separator" % (path, line_no))
                continue
            name, payload = line.split(":", 1)
            values = []
            for token in payload.replace(",", " ").split():
                try:
                    values.append(float(token))
