import sys
from collections import Counter


def get_quadrant(x, y):
    """Return the quadrant (1-4) of point (x, y), or 0 if it lies on an axis."""
    if x == 0 or y == 0:
        return 0
    if x > 0:
        return 1 if y > 0 else 4
    return 2 if y > 0 else 3


def parse_line(line):
    """Parse 'x,y' (or whitespace separated) into a pair of floats."""
    parts = line.replace(",", " ").split()
    if len(parts) != 2:
        raise ValueError("expected two coordinates, got %r" % line.strip())
    return float(parts[0]), float(parts[1])


def read_points(path):
    """Read points from a text file, skipping blank lines and # comments."""
    points = []
    with open(path, encoding="utf-8") as f:
        for lineno, line in enumerate(f, start=1):
            stripped = line.strip()
            if not stripped or stripped.startswith("#"):
                continue
            try:
                points.append(parse_line(stripped))
            except ValueError as exc:
                raise ValueError("%s:%d: %s" % (path, lineno, exc)) from None
    return points


def format_number(value):
    return "%g" % value


def write_report(path, points):
    """Write one classified point per line and return the quadrant counts."""
    counts = Counter()
    with open(path, "w", encoding="utf-8") as f:
        f.write("x\ty\tquadrant\n")
        for x, y in points:
            quadrant = get_quadrant(x, y)
            counts[quadrant] += 1
            f.write("%s\t%s\t%d\n" % (format_number(x), format_number(y), quadrant))
    return counts


def write_axis_points(path, points):
    """Write the points that lie on an axis, which belong to no quadrant."""
    with open(path, "w", encoding="utf-8") as f:
        for x, y in points:
            if get_quadrant(x, y) == 0:
                f.write("%s,%s\n" % (format_number(x), format_number(y)))


def write_summary(path, counts):
    labels = {0: "on axis", 1: "quadrant I", 2: "quadrant II",
              3: "quadrant III", 4: "quadrant IV"}
    with open(path, "w", encoding="utf-8") as f:
        for key in (1, 2, 3, 4, 0):
            f.write("%s,%d\n" % (labels[key], counts.get(key, 0)))


def append_log(path, message):
    with open(path, "a", encoding="utf-8") as f:
        f.write(message + "\n")


def main(argv):
    if len(argv) != 2:
        print("usage: %s POINTS_FILE" % argv[0], file=sys.stderr)
        return 2
    source = argv[1]
    points = read_points(source)
    counts = write_report("quadrants.tsv", points)
    write_axis_points("quadrants_on_axis.csv", points)
    write_summary("quadrants_summary.csv", counts)
    append_log("quadrants.log", "classified %d point(s) from %s" % (len(points), source))
    for key in (1, 2, 3, 4, 0):
        print("%d: %d" % (key, counts.get(key, 0)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

