import sys


def calculate_median(numbers):
    """Return the median of a list of numbers without modifying the input."""
    if not numbers:
        return None
    ordered = sorted(numbers)
    middle = len(ordered) // 2
    if len(ordered) % 2 == 1:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2


def read_manifest(path):
    """Read a manifest file listing one data file path per line."""
    paths = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            entry = line.strip()
            if entry and not entry.startswith("#"):
                paths.append(entry)
    return paths


def read_series(path):
    """Read whitespace/comma separated numbers from a data file."""
    with open(path, encoding="utf-8") as f:
        text = f.read()
    return parse_numbers(text)


def append_history(path, rows):
    """Append one line per analysed file to a cumulative history log."""
    with open(path, "a", encoding="utf-8") as f:
        for name, count, median, error in rows:
            f.write("%s\t%d\t%s\t%s\n" % (name, count, format_value(median), error or "ok"))


def parse_numbers(text):
    values = []
    for token in text.replace(",", " ").split():
        try:
            values.append(float(token))
        except ValueError:
            raise ValueError("not a number: %r" % token)
    return values


def format_value(value):
    if value is None:
        return "no data"
    if float(value).is_integer():
        return str(int(value))
    return "%.4g" % value


def write_report(path, rows):
    with open(path, "w", encoding="utf-8") as f:
        f.write("Median report\n")
        f.write("=" * 13 + "\n")
        for name, count, median, error in rows:
            if error:
                f.write("%s: error (%s)\n" % (name, error))
            else:
                f.write("%s: n=%d median=%s\n" % (name, count, format_value(median)))


def write_csv(path, rows):
    with open(path, "w", encoding="utf-8") as f:
        f.write("file,count,median,error\n")
        for name, count, median, error in rows:
