import json
import sys


def load_tasks(path):
    """Read the task definitions from a JSON file."""
    with open(path, encoding="utf-8") as f:
        raw = json.load(f)
    tasks = []
    for entry in raw:
        tasks.append({
            "name": str(entry["name"]),
            "dependencies": [str(d) for d in entry.get("dependencies", [])],
        })
    return tasks


def load_completed(path):
    """Read completed task names, one per line, ignoring blanks and comments."""
    names = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            name = line.strip()
            if name and not name.startswith("#"):
                names.append(name)
    return names


def append_completed(path, names):
    """Record newly finished task names in the completed-tasks file."""
    with open(path, "a", encoding="utf-8") as f:
        for name in names:
            f.write(name + "\n")


def find_task(task_name, tasks):
    for task in tasks:
        if task["name"] == task_name:
            return task
    raise KeyError("unknown task: %s" % task_name)


def unmet_dependencies(task_name, tasks, completed_tasks):
    task = find_task(task_name, tasks)
    return [d for d in task["dependencies"] if d not in completed_tasks]


def has_unmet_dependencies(task_name, tasks, completed_tasks):
    return bool(unmet_dependencies(task_name, tasks, completed_tasks))


def ready_tasks(tasks, completed_tasks):
    return [t["name"] for t in tasks
            if t["name"] not in completed_tasks
            and not has_unmet_dependencies(t["name"], tasks, completed_tasks)]


def write_report(path, tasks, completed_tasks):
    """Write a human readable table of blocked tasks."""
    with open(path, "w", encoding="utf-8") as f:
        f.write("task\tblocked\tmissing\n")
        for task in tasks:
            missing = unmet_dependencies(task["name"], tasks, completed_tasks)
            f.write("%s\t%s\t%s\n" % (task["name"],
                                      "yes" if missing else "no",
                                      ",".join(missing) or "-"))


def write_summary(path, tasks, completed_tasks):
    """Write a machine readable summary for downstream schedulers."""
    summary = {
        "ready": ready_tasks(tasks, completed_tasks),
        "blocked": {t["name"]: unmet_dependencies(t["name"], tasks, completed_tasks)
                    for t in tasks
                    if has_unmet_dependencies(t["name"], tasks, completed_tasks)},
    }
    with open(path, "w", encoding="utf-8") as f:
        json.dump(summary, f, indent=2, sort_keys=True)


def main(argv):
    if len(argv) != 5:
        print("usage: %s tasks.json completed.txt report.tsv summary.json" % argv[0])
        return 1
    tasks_path, completed_path, report_path, summary_path = argv[1:]
    tasks = load_tasks(tasks_path)
    completed = load_completed(completed_path)
    write_report(report_path, tasks, completed)
    write_summary(summary_path, tasks, completed)
    newly_done = ready_tasks(tasks, completed)
    append_completed(completed_path, newly_done)
    for task in tasks:
        state = "blocked" if has_unmet_dependencies(task["name"], tasks, completed) else "clear"
        print("%s: %s" % (task["name"], state))
    print("marked complete: %s" % (", ".join(newly_done) or "nothing"))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

