import os
import re
import sys

PHONE_PATTERN = re.compile(r"^\d{3}[- ]?\d{3}[- ]?\d{4}$")


def is_valid_us_phone_number(number):
    if not isinstance(number, str):
        return False
    return PHONE_PATTERN.match(number) is not None


def read_numbers(path):
    numbers = []
    f = open(path, "r", encoding="utf-8")
    for line in f:
        candidate = line.strip()
        if candidate:
            numbers.append(candidate)
    f.close()
    return numbers


def load_known_numbers(path):
    known = set()
    if os.path.exists(path):
        f = open(path, "r", encoding="utf-8")
        for line in f:
            known.add(line.strip())
        f.close()
    return known


def write_numbers(path, numbers):
    f = open(path, "w", encoding="utf-8")
    for number in numbers:
        f.write(number + "\n")
    f.close()


def write_report(path, source, valid, duplicates, invalid):
    f = open(path, "w", encoding="utf-8")
    f.write("Phone number validation report\n")
    f.write("source: {}\n".format(source))
    f.write("total: {}\n".format(len(valid) + len(duplicates) + len(invalid)))
    f.write("new valid: {}\n".format(len(valid)))
    f.write("already known: {}\n".format(len(duplicates)))
    f.write("invalid: {}\n\n".format(len(invalid)))
    for number in invalid:
        f.write("rejected: {}\n".format(number))
    f.close()


def append_audit_log(path, source, valid_count, invalid_count):
    f = open(path, "a", encoding="utf-8")
    f.write("{}\t{}\t{}\n".format(source, valid_count, invalid_count))
    f.close()


def format_number(number):
    digits = number.replace("-", "").replace(" ", "")
    return "{}-{}-{}".format(digits[:3], digits[3:6], digits[6:])


def classify(numbers, known):
    valid = []
    duplicates = []
    invalid = []
