import sys
from collections import defaultdict


def generate_initials(full_name):
    if not isinstance(full_name, str):
        raise TypeError("full name must be a string")
    parts = full_name.split()
    return "".join(part[0].upper() + "." for part in parts)


def read_names(path):
    names = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            stripped = line.strip()
            if stripped:
                names.append(stripped)
    return names


def load_overrides(path):
    overrides = {}
    with open(path, encoding="utf-8") as f:
        for line in f:
            if "\t" not in line:
                continue
            name, initials = line.rstrip("\n").split("\t", 1)
            overrides[" ".join(name.split()).lower()] = initials.strip()
    return overrides


def build_rows(names, overrides):
    rows = []
    for name in names:
        key = " ".join(name.split()).lower()
        rows.append((name, overrides.get(key, generate_initials(name))))
    return rows


def write_report(path, rows):
    with open(path, "w", encoding="utf-8") as f:
        f.write("name,initials\n")
        for name, initials in rows:
            f.write('"{}",{}\n'.format(" ".join(name.split()), initials))


def write_collisions(path, rows):
    groups = defaultdict(list)
    for name, initials in rows:
        groups[initials].append(" ".join(name.split()))
    shared = {k: v for k, v in groups.items() if len(v) > 1}
    with open(path, "w", encoding="utf-8") as f:
        for initials in sorted(shared):
            f.write("{}: {}\n".format(initials, ", ".join(sorted(shared[initials]))))
    return len(shared)


def append_log(path, processed, collisions):
    with open(path, "a", encoding="utf-8") as f:
        f.write("processed={} collision_groups={}\n".format(processed, collisions))


def main(argv):
    if len(argv) != 5:
        print("usage: initials.py NAMES OVERRIDES REPORT COLLISIONS", file=sys.stderr)
        return 2
    names_path, overrides_path, report_path, collisions_path = argv[1:]
    names = read_names(names_path)
    overrides = load_overrides(overrides_path)
    rows = build_rows(names, overrides)
    write_report(report_path, rows)
    collisions = write_collisions(collisions_path, rows)
    append_log(report_path + ".log", len(rows), collisions)
    print("wrote {} rows to {}".format(len(rows), report_path))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

